 UPDATE public.authors SET evaluation='李白诗歌想象瑰丽，语言自然明快。山水、饮酒与明月反复入诗，既写豪情，也写客居与离别。',timeline='[{"year":"701","event":"李白出生。"},{"year":"742","event":"应召来到长安，供奉翰林。"},{"year":"744","event":"离开长安，重启漫游。"},{"year":"762","event":"卒于当涂。"}]'::jsonb,editorial_sources='[{"title":"年表资料 · 香港教育局","url":"https://www.edb.gov.hk/attachment/tc/curriculum-development/kla/chi-edu/resources/secondary-edu/lang/20240708_PDF3.pdf"}]'::jsonb WHERE id='li-bai';
 UPDATE public.authors SET evaluation='柳永擅长把人物行动、眼前景物和内心变化铺叙成一条清楚的线索。他大量创作慢词，扩展了词写行旅、都市和离别的篇幅，短章也常以口语点透情感。《凤栖梧》两首便各有侧重，一首以望远、试醉写相思，一首从回廊、半掩的门写到室内相会。王国维借「衣带渐宽」两句说明求学立业的第二境界，体现了柳词在后世的另一种读法。',timeline='[{"year":"早年","event":"初名三变，后以柳永、字耆卿行世，早年已以填词闻名。"},{"year":"1034","event":"宋仁宗景祐元年登进士第。"},{"year":"晚年","event":"官至屯田员外郎，后世称柳屯田。"}]'::jsonb,editorial_sources='[{"title":"四库本《乐章集》提要","url":"https://ctext.org/wiki.pl?chapter=442813&if=gb"},{"title":"叶梦得《避暑录话》卷下","url":"https://www.shidianguji.com/zh/book/NGJ892411999011173118943/chapter/1luz5ytthjwhg"},{"title":"王国维《人间词话》","url":"https://zh.wikisource.org/zh-hans/人間詞話_(1926)"}]'::jsonb WHERE id='ad964d3e-4467-455c-ac2f-a4850ff55a8b';
 UPDATE public.authors SET evaluation='赵令畤的商调《蝶恋花》把传奇情节拆成可讲可唱的段落。以「尺素重重」一阕为例，散文交代莺莺所寄的信物和来历，词则让人物借玉环、彩丝、泪竹说出相思。散文推进故事，曲词留住情绪，是理解宋代鼓子词的重要例子。《侯鲭录》还保存了他与苏轼等人的交游、诗话和笔记材料。',timeline='[{"year":"1091","event":"苏轼出守颍州，与签书颍州公事的赵令畤相识，后来为他改字德麟。"},{"year":"绍兴初","event":"袭封安定郡王，同知行在大宗正事。"},{"year":"1134","event":"卒于宋高宗绍兴四年。"}]'::jsonb,editorial_sources='[{"title":"苏轼《赵德麟字说》","url":"https://wk.100ke.info/zh-hans/趙德麟字說"},{"title":"赵令畤《侯鲭录》卷五","url":"https://ctext.org/wiki.pl?chapter=6359952&if=en&remap=gb"},{"title":"《侯鲭录》四库本提要","url":"https://zh.wikisource.org/zh-hans/侯鯖錄"}]'::jsonb WHERE id='0984b151-da94-4975-ad4e-f1d21e301a9a';
 UPDATE public.authors SET evaluation='杨万里在《卢溪先生文集序》中既肯定王庭珪诗句之工，也看重他面对时局时敢于直言。王庭珪送别胡铨的诗能见其刚直，本篇贺丁氏兄弟登科，则显示他能把日常酬赠写得轻快有生气。结尾以商高宗求傅说的旧典托出对新科进士的期待，提升了贺词的分量。',timeline='[{"year":"1118","event":"宋徽宗政和八年登进士第，后任茶陵县丞。"},{"year":"绍兴年间","event":"胡铨因上疏反对议和遭贬，王庭珪作诗送行，后来因送别诗获罪。"},{"year":"1170","event":"宋孝宗乾道六年除直敷文阁。"},{"year":"1172","event":"卒。其诗文收入《卢溪文集》。"}]'::jsonb,editorial_sources='[{"title":"《卢溪文集》四库本提要","url":"https://zh.wikisource.org/zh-hans/盧溪文集_(四庫全書本)/全覽1"},{"title":"杨万里《卢溪先生文集序》","url":"https://zh.wikisource.org/zh-hans/盧溪先生文集序"}]'::jsonb WHERE id='c384a593-a965-4f3f-a12a-fcc07519f964';
 UPDATE public.poems SET creation_background='《全宋词》将本篇编在柳永小石调《凤栖梧》三首中的第二首。《凤栖梧》又名《蝶恋花》。本篇通过登楼、望远和饮酒写相思。底本未标明作年、地点或所思之人。王国维后来借结尾两句比喻求学立业的第二重境界，这是此词在近代的一次重要接受。',background_source='{"title":"《全宋词》柳永卷","url":"https://www.shigeku.org/xlib/gd/qsc/0003.htm"}'::jsonb WHERE id='df844ca7-6ad7-484d-accc-b450863ccd11';
 UPDATE public.poems SET creation_background='本篇是《全宋词》所收柳永小石调《凤栖梧》三首中的第三首。词中以夜间寻访和男女相会为情境，蜀锦、丝障、熏炉、斗帐等器物构成了室内景象。底本未标明作年、地点或人物身份，具体情境可从词中所写理解。',background_source='{"title":"《全宋词》柳永卷","url":"https://www.shigeku.org/xlib/gd/qsc/0003.htm"}'::jsonb WHERE id='d4c60512-b5be-4030-9c6a-eb64d333d06e';
 UPDATE public.poems SET creation_background='本篇出自赵令畤据唐代元稹《莺莺传》（又名《会真记》）改编的商调《蝶恋花》鼓子词，见《侯鲭录》卷五。原组作品用散文讲述故事，间以词章供歌唱。本篇对应崔莺莺写信并寄赠玉环、彩丝和文竹茶具的段落。词中的女性口吻来自故事人物。',background_source='{"title":"赵令畤《侯鲭录》卷五","url":"https://ctext.org/wiki.pl?chapter=6359952&if=en&remap=gb"}'::jsonb WHERE id='abea40d4-abf5-4d3e-9d57-abb9a3655222';
 UPDATE public.poems SET creation_background='《全宋词》题下注「赠丁爽、丁旦及第」，点明王庭珪写此词庆贺丁氏兄弟登科。上片想象两人一同入月宫折桂，下片由临江送别转为期许二人日后获朝廷重用。具体作年暂缺可核的记载。',background_source='{"title":"《全宋词》王庭珪卷","url":"https://ctext.org/wiki.pl?chapter=463427&if=gb&remap=gb"}'::jsonb WHERE id='573d382e-12e4-4f3c-88b9-c18e16ad382e';
 UPDATE public.poems SET annotation_notes='[{"word":"朕","explanation":"我，此处为招魂者（一说为屈原）自称。","line":0,"start":0,"end":1,"source_text":"朕幼清以廉洁兮，身服义而未沫。"},{"word":"服义","explanation":"践行道义。","line":0,"start":9,"end":11,"source_text":"朕幼清以廉洁兮，身服义而未沫。"},{"word":"未沫","explanation":"未曾衰减。","line":0,"start":12,"end":14,"source_text":"朕幼清以廉洁兮，身服义而未沫。"},{"word":"主","explanation":"秉持。","line":1,"start":0,"end":1,"source_text":"主此盛德兮，牵于俗而芜秽。"},{"word":"牵于俗","explanation":"被世俗拖累。","line":1,"start":6,"end":9,"source_text":"主此盛德兮，牵于俗而芜秽。"},{"word":"芜秽","explanation":"指德行受到污染。","line":1,"start":10,"end":12,"source_text":"主此盛德兮，牵于俗而芜秽。"},{"word":"上","explanation":"指楚王。","line":2,"start":0,"end":1,"source_text":"上无所考此盛德兮，长离殃而愁苦。"},{"word":"考","explanation":"察知。","line":2,"start":3,"end":4,"source_text":"上无所考此盛德兮，长离殃而愁苦。"},{"word":"离殃","explanation":"遭遇灾祸，离通“罹”。","line":2,"start":10,"end":12,"source_text":"上无所考此盛德兮，长离殃而愁苦。"},{"word":"帝","explanation":"天帝。","line":3,"start":0,"end":1,"source_text":"帝告巫阳曰：“有人在下，我欲辅之。魂魄离散，汝筮予之。”"},{"word":"巫阳","explanation":"古代神话中的神巫，善招魂。","line":3,"start":2,"end":4,"source_text":"帝告巫阳曰：“有人在下，我欲辅之。魂魄离散，汝筮予之。”"},{"word":"筮","explanation":"用蓍草占卜。","line":3,"start":23,"end":24,"source_text":"帝告巫阳曰：“有人在下，我欲辅之。魂魄离散，汝筮予之。”"},{"word":"予之","explanation":"把魂魄还给那人。","line":3,"start":24,"end":26,"source_text":"帝告巫阳曰：“有人在下，我欲辅之。魂魄离散，汝筮予之。”"},{"word":"上","explanation":"指楚王。","line":4,"start":9,"end":10,"source_text":"巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”"},{"word":"帝","explanation":"天帝。","line":4,"start":10,"end":11,"source_text":"巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”"},{"word":"巫阳","explanation":"古代神话中的神巫，善招魂。","line":4,"start":0,"end":2,"source_text":"巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”"},{"word":"筮","explanation":"用蓍草占卜。","line":4,"start":17,"end":18,"source_text":"巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”"},{"word":"予之","explanation":"把魂魄还给那人。","line":4,"start":18,"end":20,"source_text":"巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”"},{"word":"掌梦","explanation":"掌管占梦的官，巫阳表示招魂本是掌梦之职。","line":4,"start":6,"end":8,"source_text":"巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”"},{"word":"谢","explanation":"衰谢，指魂魄消散。","line":4,"start":24,"end":25,"source_text":"巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”"},{"word":"巫阳","explanation":"古代神话中的神巫，善招魂。","line":5,"start":0,"end":2,"source_text":"巫阳焉乃下招曰：魂兮归来！去君之恒干，何为四方些？"},{"word":"恒干","explanation":"常住的躯体。些（suò）：楚地巫术招魂时的衬字，无实义。","line":5,"start":16,"end":18,"source_text":"巫阳焉乃下招曰：魂兮归来！去君之恒干，何为四方些？"},{"word":"雕题黑齿","explanation":"指南方蛮夷，额上刻纹、牙齿染黑。醢（hǎi）：肉酱。","line":12,"start":0,"end":4,"source_text":"雕题黑齿，得人肉以祀，以其骨为醢些。"},{"word":"封狐","explanation":"大狐狸。雄虺（huǐ）：雄性的毒蛇。","line":13,"start":5,"end":7,"source_text":"蝮蛇蓁蓁，封狐千里些。"},{"word":"倏忽","explanation":"速度极快。","line":14,"start":7,"end":9,"source_text":"雄虺九首，往来倏忽，吞人以益其心些。"},{"word":"雷渊","explanation":"神话中的西方深渊，人入则被碾成碎末。爢（mí）散：粉碎。","line":17,"start":2,"end":4,"source_text":"旋入雷渊，爢散而不可止些。"},{"word":"壶","explanation":"通“瓠”，葫芦。菅（jiān）：茅草。","line":19,"start":8,"end":9,"source_text":"赤蚁若象，玄蜂若壶些。"},{"word":"极","explanation":"尽兴。","line":22,"start":10,"end":11,"source_text":"彷徉无所倚，广大无所极些。"},{"word":"遗贼","explanation":"留下灾祸。","line":23,"start":6,"end":8,"source_text":"归来兮！恐自遗贼些。"},{"word":"增冰","explanation":"层冰，增通“层”。","line":25,"start":0,"end":2,"source_text":"增冰峨峨，飞雪千里些。"},{"word":"峨峨","explanation":"高耸貌。","line":25,"start":2,"end":4,"source_text":"增冰峨峨，飞雪千里些。"},{"word":"上","explanation":"指楚王。","line":27,"start":7,"end":8,"source_text":"魂兮归来！君无上天些。"},{"word":"九关","explanation":"指天门有九重，每重都有虎豹把守。侁侁（shēn）：众多貌。","line":28,"start":2,"end":4,"source_text":"虎豹九关，啄害下人些。"},{"word":"帝","explanation":"天帝。","line":32,"start":3,"end":4,"source_text":"致命于帝，然后得瞑些。"},{"word":"幽都","explanation":"阴间地府。","line":34,"start":9,"end":11,"source_text":"魂兮归来！君无下此幽都些。"},{"word":"土伯","explanation":"地府的君主。","line":35,"start":0,"end":2,"source_text":"土伯九约，其角觺觺些。"},{"word":"九约","explanation":"身形九曲。觺觺（yí）：角尖锐貌。","line":35,"start":2,"end":4,"source_text":"土伯九约，其角觺觺些。"},{"word":"血拇","explanation":"染血的指爪。伂𬳵𬳵（pī）：奔跑迅疾貌。","line":36,"start":2,"end":4,"source_text":"敦脄血拇，逐人伂𬳵𬳵些。"},{"word":"参目","explanation":"三只眼睛。","line":37,"start":0,"end":2,"source_text":"参目虎首，其身若牛些。"},{"word":"甘人","explanation":"以吃人为乐。","line":38,"start":2,"end":4,"source_text":"此皆甘人，归来！恐自遗灾些。"},{"word":"修门","explanation":"郢都的城门。","line":39,"start":6,"end":8,"source_text":"魂兮归来！入修门些。"},{"word":"工祝","explanation":"有经验的巫师。","line":40,"start":0,"end":2,"source_text":"工祝招君，背行先些。"},{"word":"背行先","explanation":"倒退着走，在前面为魂引路。","line":40,"start":5,"end":8,"source_text":"工祝招君，背行先些。"},{"word":"秦篝","explanation":"秦地产的竹笼，用来装招魂的衣物。","line":41,"start":0,"end":2,"source_text":"秦篝齐缕，郑绵络些。"},{"word":"齐缕","explanation":"齐地产的丝线。","line":41,"start":2,"end":4,"source_text":"秦篝齐缕，郑绵络些。"},{"word":"郑绵络","explanation":"郑地产的丝棉织物，都是招魂用具。","line":41,"start":5,"end":8,"source_text":"秦篝齐缕，郑绵络些。"},{"word":"邃宇","explanation":"幽深的屋宇。","line":46,"start":2,"end":4,"source_text":"高堂邃宇，槛层轩些。"},{"word":"槛层轩","explanation":"层层走廊都有栏杆。","line":46,"start":5,"end":8,"source_text":"高堂邃宇，槛层轩些。"},{"word":"网户","explanation":"刻有网状花纹的门户。","line":48,"start":0,"end":2,"source_text":"网户朱缀，刻方连些。"},{"word":"朱缀","explanation":"用朱砂涂的连接部分。","line":48,"start":2,"end":4,"source_text":"网户朱缀，刻方连些。"},{"word":"川谷径复","explanation":"溪流在院中回环往复。","line":50,"start":0,"end":4,"source_text":"川谷径复，流潺湲些。"},{"word":"光风","explanation":"雨过后带着日光的风。","line":51,"start":0,"end":2,"source_text":"光风转蕙，泛崇兰些。"},{"word":"崇兰","explanation":"丛生的兰草。","line":51,"start":6,"end":8,"source_text":"光风转蕙，泛崇兰些。"},{"word":"奥","explanation":"屋子的内室。","line":52,"start":3,"end":4,"source_text":"经堂入奥，朱尘筵些。"},{"word":"朱尘筵","explanation":"红色的顶棚，铺着竹席。","line":52,"start":5,"end":8,"source_text":"经堂入奥，朱尘筵些。"},{"word":"砥室","explanation":"用磨平的石板砌的屋子。","line":53,"start":0,"end":2,"source_text":"砥室翠翘，挂曲琼些。"},{"word":"翠翘","explanation":"翠鸟的羽毛做的装饰。","line":53,"start":2,"end":4,"source_text":"砥室翠翘，挂曲琼些。"},{"word":"曲琼","explanation":"玉制的钩子。","line":53,"start":6,"end":8,"source_text":"砥室翠翘，挂曲琼些。"},{"word":"罗帱","explanation":"丝制的帐子。","line":55,"start":5,"end":7,"source_text":"蒻阿拂壁，罗帱张些。"},{"word":"纂组绮缟","explanation":"各色丝带和丝绸。","line":56,"start":0,"end":4,"source_text":"纂组绮缟，结琦璜些。"},{"word":"琦璜","explanation":"美玉。","line":56,"start":6,"end":8,"source_text":"纂组绮缟，结琦璜些。"},{"word":"九侯淑女","explanation":"各诸侯进献的美女。盛鬋（jiǎn）：浓密的鬓发。","line":60,"start":0,"end":4,"source_text":"九侯淑女，多迅众些。"},{"word":"謇","explanation":"发语词。","line":63,"start":5,"end":6,"source_text":"弱颜固植，謇其有意些。"},{"word":"姱容修态","explanation":"美好的容貌，修长的体态。絚（gēng）：充满。","line":64,"start":0,"end":4,"source_text":"姱容修态，絚洞房些。"},{"word":"靡颜腻理","explanation":"皮肤细腻光滑。遗视矊（mián）：含情脉脉地远看。","line":66,"start":0,"end":4,"source_text":"靡颜腻理，遗视矊些。"},{"word":"芙蓉","explanation":"荷花。","line":72,"start":0,"end":2,"source_text":"芙蓉始发，杂芰荷些。"},{"word":"芰荷","explanation":"菱角和荷叶。","line":72,"start":6,"end":8,"source_text":"芙蓉始发，杂芰荷些。"},{"word":"屏风","explanation":"水葵，一种水生植物。","line":73,"start":2,"end":4,"source_text":"紫茎屏风，文缘波些。"},{"word":"低","explanation":"通“抵”，到达。","line":75,"start":3,"end":4,"source_text":"轩辌既低，步骑罗些。"},{"word":"兰薄","explanation":"丛生的兰草。","line":76,"start":0,"end":2,"source_text":"兰薄户树，琼木篱些。"},{"word":"琼木","explanation":"玉树。","line":76,"start":5,"end":7,"source_text":"兰薄户树，琼木篱些。"},{"word":"黄梁","explanation":"黄小米。","line":79,"start":6,"end":8,"source_text":"稻粢穱麦，挐黄梁些。"},{"word":"吴羹","explanation":"吴地风味的羹汤。胹（ér）鳖：炖甲鱼。","line":82,"start":6,"end":8,"source_text":"和酸若苦，陈吴羹些。"},{"word":"炮羔","explanation":"烤小羊。","line":83,"start":2,"end":4,"source_text":"胹鳖炮羔，有柘浆些。"},{"word":"柘浆","explanation":"甘蔗汁。","line":83,"start":6,"end":8,"source_text":"胹鳖炮羔，有柘浆些。"},{"word":"露鸡","explanation":"卤鸡。臛蠵（huò xī）：龟羹。","line":85,"start":0,"end":2,"source_text":"露鸡臛蠵，厉而不爽些。"},{"word":"厉","explanation":"味道浓烈。","line":85,"start":5,"end":6,"source_text":"露鸡臛蠵，厉而不爽些。"},{"word":"不爽","explanation":"不伤胃口。","line":85,"start":7,"end":9,"source_text":"露鸡臛蠵，厉而不爽些。"},{"word":"蜜饵","explanation":"蜜糕。餦餭（zhāng huáng）：麦芽糖。","line":86,"start":2,"end":4,"source_text":"粔籹蜜饵，有餦餭些。"},{"word":"瑶浆","explanation":"美酒。","line":87,"start":0,"end":2,"source_text":"瑶浆蜜勺，实羽觞些。"},{"word":"蜜勺","explanation":"加了蜜的甜酒。","line":87,"start":2,"end":4,"source_text":"瑶浆蜜勺，实羽觞些。"},{"word":"羽觞","explanation":"鸟形的酒杯。","line":87,"start":6,"end":8,"source_text":"瑶浆蜜勺，实羽觞些。"},{"word":"冻饮","explanation":"冰过的酒。酎（zhòu）：醇酒。","line":88,"start":2,"end":4,"source_text":"挫糟冻饮，酎清凉些。"},{"word":"眇视","explanation":"眼波流转的样子。","line":95,"start":2,"end":4,"source_text":"嬉光眇视，目曾波些。"},{"word":"衽若交竿","explanation":"舞女的衣襟翻飞像交叉的竹竿。","line":99,"start":0,"end":4,"source_text":"衽若交竿，抚案下些。"},{"word":"抚案下","explanation":"按着节拍退下。","line":99,"start":5,"end":8,"source_text":"衽若交竿，抚案下些。"},{"word":"大吕","explanation":"古乐调名。","line":102,"start":6,"end":8,"source_text":"吴歈蔡讴，奏大吕些。"},{"word":"班","explanation":"纷乱的样子。","line":104,"start":5,"end":6,"source_text":"放敶组缨，班其相纷些。"},{"word":"妖玩","explanation":"妖艳的玩物，指美女。","line":105,"start":2,"end":4,"source_text":"郑卫妖玩，来杂陈些。"},{"word":"象棋","explanation":"象牙做的棋子。六簙（bó）：古代的一种博戏，共六枚棋子。","line":107,"start":2,"end":4,"source_text":"菎蔽象棋，有六簙些。"},{"word":"分曹","explanation":"分成两队。","line":108,"start":0,"end":2,"source_text":"分曹并进，遒相迫些。"},{"word":"枭","explanation":"博戏中取胜的棋子。","line":109,"start":1,"end":2,"source_text":"成枭而牟，呼五白些。"},{"word":"牟","explanation":"加倍取胜。","line":109,"start":3,"end":4,"source_text":"成枭而牟，呼五白些。"},{"word":"五白","explanation":"博戏中最吉利的骰色。","line":109,"start":6,"end":8,"source_text":"成枭而牟，呼五白些。"},{"word":"铿钟","explanation":"敲钟。簴（jù）：挂钟的架子。揳（jiá）：弹奏。","line":111,"start":0,"end":2,"source_text":"铿钟摇簴，揳梓瑟些。"},{"word":"梓瑟","explanation":"梓木做的瑟。","line":111,"start":6,"end":8,"source_text":"铿钟摇簴，揳梓瑟些。"},{"word":"兰芳假","explanation":"文辞像兰花一样芬芳。","line":114,"start":5,"end":8,"source_text":"结撰至思，兰芳假些。"},{"word":"极","explanation":"尽兴。","line":115,"start":3,"end":4,"source_text":"人有所极，同心赋些。"},{"word":"先故","explanation":"故旧祖先。","line":116,"start":6,"end":8,"source_text":"酎饮尽欢，乐先故些。"},{"word":"献岁发春","explanation":"新年开春。汨（yù）：行走迅疾的样子。","line":118,"start":3,"end":7,"source_text":"乱曰：献岁发春兮，汨吾