onb WHERE id='cf8de612-9170-4326-889b-52cc0489d313' AND content='宣州当涂县令　　李阳冰

李白，字太白，陇西成纪人，凉武昭王暠九世孙。蝉联圭组，世为显著。中叶非罪，谪居条支，易姓为名，然自穷蝉至舜，七世为庶，累世不大曜，亦可叹焉。神龙之始，逃归于蜀，复指李树而生伯阳。惊姜之夕，长庚入梦，故生而名白，以太白字之。世称太白之精得之矣。不读非圣之书，耻为郑、卫之作，故其言多似天仙之辞。凡所著称，言多讽兴。自三代已来，风骚之后，驰驱屈、宋、鞭挞扬、马，千载独步，唯公一人。故王公趋风，列岳结轨；群贤翕习，如鸟归凤。卢黄门云：“陈拾遗横制颓波，天下质文翕然一变，至今朝诗体，尚有梁、陈宫掖之风。至公大变，扫地并尽；今古文集，遏而不行。唯公文章，横被六合，可谓力敌造化欤。天宝中，皇祖下诏，征就金马，降辇步迎如见绮、皓。以七宝床赐食，御手调羹以饭之，谓曰：卿是布衣，名为朕知，非素蓄道义何以及此？置于金銮殿，出入翰林中，问以国政，潜草诏诰，人无知者。丑正同列，害能成谤，格言不入，帝用疏之。公乃浪迹纵酒，以自昏秽。咏歌之际，屡称东山。又与贺知章、崔宗之等自为八仙之游，谓公谪仙人，朝列赋谪仙之歌，凡数百首，多言公之不得意。天子知其不可留，乃赐金归之。遂就从祖拜留采访大使彦，请北海高天师授道箓于齐州紫极宫。将东归蓬莱，仍羽人驾丹丘耳。阳冰试弦歌于当涂，心非所好，公遐不弃我，扁舟而相欢。临当挂冠，公又疾殛。草稿万卷，手集未修。枕上授简，俾余为序。论《郑睢》之义，始愧卜商；明《春秋》之辞，终惭杜预。自中原有事，公避地八年；当时著述，十丧其九，今所存者，皆得之他人焉。时宝应元年十一月乙酉也。' AND annotation='①本篇为《李太白集》卷首序文汇编，共收唐五代相关序、志、碑记六篇，分别为李阳冰《草堂集序》、魏颢《李翰林集序》、乐史《李翰林别集序》、李华《故翰林学士李君墓志并序》、刘全白《唐故翰林学士李君碣记》、范传正《唐左拾遗翰林学士李公新墓碑并序》、裴敬《翰林学士李公墓碑》。
②圭组：玉圭与印绶，代指官职爵位。条支：古西域国名，此处泛指西域边地。长庚：即金星，古代又名太白星，传说李白之母梦长庚入怀而生李白。
③陈拾遗：指陈子昂，曾官右拾遗。梁陈宫掖之风：指南朝梁陈时期浮靡绮艳的宫体诗风。金马：汉代有金马门，为待诏之处，此处指唐代翰林院。绮皓：即汉初商山四皓中的绮里季，泛指德高望重的隐士。
④道箓：道教的入道凭证，受箓后方为正式道士。弦歌：孔子弟子子游任武城宰，以弦歌教化民众，后以“弦歌”代指出任地方县令。
⑤宝应元年：公元762年，为李白卒年。魏颢：又名魏万，李白友人，曾漫游千里寻访李白，得李白托付文稿。
⑥木芍药：即牡丹，唐代宫中称牡丹为木芍药。沉香亭：唐代兴庆宫内宫殿名，为玄宗与杨贵妃宴游之处。高力士：唐玄宗时期当权宦官，传说曾为李白脱靴。
⑦郭子仪：唐代中兴名将，传说李白在并州时曾救过犯事的郭子仪，后李白因永王李璘事获罪，郭子仪请以官爵为其赎罪。
⑧姑熟：即当涂，今安徽当涂县。青山：又名谢公山，因南朝诗人谢朓曾居于此而得名，为李白埋骨之处。
⑨范传正：唐代宣歙池观察使，曾主持迁葬李白墓至青山，为其立碑。伯禽：李白之子，李白去世后居于当涂，早卒。
⑩三绝：唐文宗时下诏，以李白诗歌、裴旻剑舞、张旭草书为“三绝”。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"畦","explanation":"田垄、田块。","line":0,"start":1,"end":2,"source_text":"万畦新稻傍山村，数里深松到寺门。"},{"word":"傍","explanation":"靠近。","line":0,"start":4,"end":5,"source_text":"万畦新稻傍山村，数里深松到寺门。"},{"word":"深松","explanation":"茂密的松林。","line":0,"start":10,"end":12,"source_text":"万畦新稻傍山村，数里深松到寺门。"},{"word":"穉子","explanation":"同“稚子”，这里指年少的内弟阎伯均。","line":1,"start":5,"end":7,"source_text":"幸有香茶留穉子，不堪秋草送王孙。"},{"word":"王孙","explanation":"古代对贵族子弟的通称，此处代指阎伯均。","line":1,"start":13,"end":15,"source_text":"幸有香茶留穉子，不堪秋草送王孙。"},{"word":"烟尘","explanation":"指战乱。","line":2,"start":0,"end":2,"source_text":"烟尘怨别唯愁隔，井邑萧条谁忍论。"},{"word":"井邑","explanation":"市井村落。","line":2,"start":8,"end":10,"source_text":"烟尘怨别唯愁隔，井邑萧条谁忍论。"},{"word":"临歧","explanation":"走到岔路口，指分别之处。","line":3,"start":2,"end":4,"source_text":"莫怪临歧独垂泪，魏舒偏念外家恩。"},{"word":"魏舒","explanation":"西晋大臣，年少时寄养在外家（外祖父家），对外家恩德感念至深，此处诗人以魏舒自比，说自己顾念和内弟的外戚情分。","line":3,"start":8,"end":10,"source_text":"莫怪临歧独垂泪，魏舒偏念外家恩。"}]'::jsonb WHERE id='d204973f-89ac-408d-a228-fb94da6eb81b' AND content='万畦新稻傍山村，数里深松到寺门。
幸有香茶留穉子，不堪秋草送王孙。
烟尘怨别唯愁隔，井邑萧条谁忍论。
莫怪临歧独垂泪，魏舒偏念外家恩。' AND annotation='①秋晓：秋天的清晨。招隐寺：寺庙名。茶宴：以茶为饮的宴聚。内弟：妻子的弟弟。江州：今江西九江一带。②畦：田垄、田块。傍：靠近。③深松：茂密的松林。④穉子：同“稚子”，这里指年少的内弟阎伯均。⑤王孙：古代对贵族子弟的通称，此处代指阎伯均。⑥烟尘：指战乱。井邑：市井村落。⑦临歧：走到岔路口，指分别之处。⑧魏舒：西晋大臣，年少时寄养在外家（外祖父家），对外家恩德感念至深，此处诗人以魏舒自比，说自己顾念和内弟的外戚情分。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"蜀锦","explanation":"蜀地所产的彩织锦。","line":0,"start":0,"end":2,"source_text":"蜀锦地衣丝步障。"},{"word":"地衣","explanation":"铺在地上的毯席。","line":0,"start":2,"end":4,"source_text":"蜀锦地衣丝步障。"},{"word":"步障","explanation":"遮挡视线的帷幕，此处用丝织成。","line":0,"start":5,"end":7,"source_text":"蜀锦地衣丝步障。"},{"word":"屈曲","explanation":"弯曲回折。","line":1,"start":0,"end":2,"source_text":"屈曲回廊，静夜闲寻访。"},{"word":"玉砌雕阑","explanation":"精美的石阶和雕饰的栏杆。","line":2,"start":0,"end":4,"source_text":"玉砌雕阑新月上。"},{"word":"朱扉","explanation":"红色的门扇。","line":3,"start":0,"end":2,"source_text":"朱扉半掩人相望。"},{"word":"旋","explanation":"随即、很快。","line":4,"start":0,"end":1,"source_text":"旋暖熏炉温斗帐。"},{"word":"熏炉","explanation":"用来熏香的炉具。","line":4,"start":2,"end":4,"source_text":"旋暖熏炉温斗帐。"},{"word":"斗帐","explanation":"形制如覆斗的小帐。","line":4,"start":5,"end":7,"source_text":"旋暖熏炉温斗帐。"},{"word":"玉树琼枝","explanation":"借玉树美枝形容人物姿容秀美。","line":5,"start":0,"end":4,"source_text":"玉树琼枝，迤逦相偎傍。"},{"word":"迤逦","explanation":"此处可理解为渐渐。","line":5,"start":5,"end":7,"source_text":"玉树琼枝，迤逦相偎傍。"},{"word":"偎傍","explanation":"相互依偎。","line":5,"start":8,"end":10,"source_text":"玉树琼枝，迤逦相偎傍。"},{"word":"春思荡","explanation":"情思荡漾。","line":6,"start":4,"end":7,"source_text":"酒力渐浓春思荡。"},{"word":"鸳鸯绣被翻红浪","explanation":"绣有鸳鸯的红被翻动，以红浪暗写亲昵。","line":7,"start":0,"end":7,"source_text":"鸳鸯绣被翻红浪。"}]'::jsonb WHERE id='d4c60512-b5be-4030-9c6a-eb64d333d06e' AND content='蜀锦地衣丝步障。
屈曲回廊，静夜闲寻访。
玉砌雕阑新月上。
朱扉半掩人相望。
旋暖熏炉温斗帐。
玉树琼枝，迤逦相偎傍。
酒力渐浓春思荡。
鸳鸯绣被翻红浪。' AND annotation='蜀锦：蜀地所产的彩织锦。地衣：铺在地上的毯席。步障：遮挡视线的帷幕，此处用丝织成。
屈曲：弯曲回折。玉砌雕阑：精美的石阶和雕饰的栏杆。朱扉：红色的门扇。
旋：随即、很快。熏炉：用来熏香的炉具。斗帐：形制如覆斗的小帐。
玉树琼枝：借玉树美枝形容人物姿容秀美。迤逦：此处可理解为渐渐。偎傍：相互依偎。
春思荡：情思荡漾。鸳鸯绣被翻红浪：绣有鸳鸯的红被翻动，以红浪暗写亲昵。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"明人眼","explanation":"指景物鲜妍，使人眼目清明。","line":0,"start":2,"end":5,"source_text":"今日明人眼，临池好驿亭。"},{"word":"临池","explanation":"驿亭临近水池。","line":0,"start":6,"end":8,"source_text":"今日明人眼，临池好驿亭。"},{"word":"丛篁","explanation":"丛生的竹子。","line":1,"start":0,"end":2,"source_text":"丛篁低地碧，高柳半天青。"},{"word":"低地碧","explanation":"低处的地面被竹影映得一片碧绿。","line":1,"start":2,"end":5,"source_text":"丛篁低地碧，高柳半天青。"},{"word":"半天青","explanation":"柳树高耸，青色的柳荫直遮到半空中。","line":1,"start":8,"end":11,"source_text":"丛篁低地碧，高柳半天青。"},{"word":"稠叠","explanation":"景物稠密重叠。","line":2,"start":0,"end":2,"source_text":"稠叠多幽事，喧呼阅使星。"},{"word":"幽事","explanation":"清幽的景致、雅事。","line":2,"start":3,"end":5,"source_text":"稠叠多幽事，喧呼阅使星。"},{"word":"喧呼","explanation":"喧闹呼叫。","line":2,"start":6,"end":8,"source_text":"稠叠多幽事，喧呼阅使星。"},{"word":"使星","explanation":"古代认为天有使臣星，下凡为朝廷使者，此处指来往的驿使。","line":2,"start":9,"end":11,"source_text":"稠叠多幽事，喧呼阅使星。"},{"word":"老夫","explanation":"作者自称。","line":3,"start":0,"end":2,"source_text":"老夫如有此，不异在郊坰。"},{"word":"郊坰","explanation":"郊外、郊野。","line":3,"start":9,"end":11,"source_text":"老夫如有此，不异在郊坰。"}]'::jsonb WHERE id='d4e537b4-9479-4bee-8de7-9a9980c7a2a0' AND content='今日明人眼，临池好驿亭。
丛篁低地碧，高柳半天青。
稠叠多幽事，喧呼阅使星。
老夫如有此，不异在郊坰。' AND annotation='明人眼：指景物鲜妍，使人眼目清明。临池：驿亭临近水池。丛篁：丛生的竹子。低地碧：低处的地面被竹影映得一片碧绿。半天青：柳树高耸，青色的柳荫直遮到半空中。稠叠：景物稠密重叠。幽事：清幽的景致、雅事。喧呼：喧闹呼叫。使星：古代认为天有使臣星，下凡为朝廷使者，此处指来往的驿使。老夫：作者自称。郊坰：郊外、郊野。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"草草","explanation":"简陋、粗疏的样子。","line":0,"start":0,"end":2,"source_text":"草草鱼梁枕水低，匆匆小驻濯涟漪。"},{"word":"鱼梁","explanation":"拦水捕鱼的堰坝，此处指卢沟桥旁的水工设施。","line":0,"start":2,"end":4,"source_text":"草草鱼梁枕水低，匆匆小驻濯涟漪。"},{"word":"枕水低","explanation":"紧贴着水面，地势低矮。","line":0,"start":4,"end":7,"source_text":"草草鱼梁枕水低，匆匆小驻濯涟漪。"},{"word":"匆匆","explanation":"形容行色匆忙。","line":0,"start":8,"end":10,"source_text":"草草鱼梁枕水低，匆匆小驻濯涟漪。"},{"word":"小驻","explanation":"短暂停留。","line":0,"start":10,"end":12,"source_text":"草草鱼梁枕水低，匆匆小驻濯涟漪。"},{"word":"濯涟漪","explanation":"在泛起波纹的河水中洗濯。","line":0,"start":12,"end":15,"source_text":"草草鱼梁枕水低，匆匆小驻濯涟漪。"},{"word":"服匿","explanation":"古代游牧民族所用的毡帐，类似蒙古包，也可指居住在毡帐中的人。","line":1,"start":2,"end":4,"source_text":"河边服匿多生口，长记轺车放鴈时。"},{"word":"生口","explanation":"本指俘虏、奴隶，此处指被金人掳掠的北宋百姓。","line":1,"start":5,"end":7,"source_text":"河边服匿多生口，长记轺车放鴈时。"},{"word":"轺车","explanation":"古代轻便的使者乘车。","line":1,"start":10,"end":12,"source_text":"河边服匿多生口，长记轺车放鴈时。"},{"word":"放鴈时","explanation":"指宋朝派遣使者出使金国，路过卢沟桥的时节，鴈同“雁”，秋季雁归，暗含对故国的思念。","line":1,"start":12,"end":15,"source_text":"河边服匿多生口，长记轺车放鴈时。"}]'::jsonb WHERE id='d70f60a1-17d0-4444-8221-7a0d1640260d' AND content='草草鱼梁枕水低，匆匆小驻濯涟漪。
河边服匿多生口，长记轺车放鴈时。' AND annotation='①草草：简陋、粗疏的样子。鱼梁：拦水捕鱼的堰坝，此处指卢沟桥旁的水工设施。枕水低：紧贴着水面，地势低矮。
②匆匆：形容行色匆忙。小驻：短暂停留。濯涟漪：在泛起波纹的河水中洗濯。
③服匿：古代游牧民族所用的毡帐，类似蒙古包，也可指居住在毡帐中的人。生口：本指俘虏、奴隶，此处指被金人掳掠的北宋百姓。
④轺车：古代轻便的使者乘车。放鴈时：指宋朝派遣使者出使金国，路过卢沟桥的时节，鴈同“雁”，秋季雁归，暗含对故国的思念。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"绣帏","explanation":"绣花的帐幔，代指女子闺房。","line":0,"start":0,"end":2,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"流苏斗帐","explanation":"装饰有穗状流苏的小方帐，为古代贵族女子的卧具。","line":0,"start":15,"end":19,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"龟甲屏风","explanation":"用龟甲纹装饰的屏风，亦有说以龟甲镶嵌为饰，是名贵的室内陈设。","line":0,"start":20,"end":24,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"七宝妆奁","explanation":"镶嵌多种珍宝的女子梳妆匣。","line":0,"start":25,"end":29,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"彩钿","explanation":"镶嵌螺贝等宝物的花饰，女子头饰的一种。","line":0,"start":30,"end":32,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"薰笼","explanation":"覆盖在香炉上的笼具，用来熏香衣被，此处写香雾从薰笼升起弥漫一帘。","line":0,"start":38,"end":40,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"金花孔雀","explanation":"指绣有孔雀、饰有金花的门帘。","line":0,"start":44,"end":48,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"绿水芙蓉","explanation":"指绘有绿水、芙蓉图案的锦制屏风。","line":0,"start":52,"end":56,"source_text":"绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。"},{"word":"鸦翅","explanation":"形容女子乌黑鬓发如同鸦鸟的翅膀。","line":1,"start":0,"end":2,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"金蝉","explanation":"古代女子的金属蝉形头饰。","line":1,"start":3,"end":5,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"妥","explanation":"妥帖，此处指头饰半垂的状态。","line":1,"start":6,"end":7,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"翠云","explanation":"形容女子头发像翠色云团。","line":1,"start":8,"end":10,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"朱凤","explanation":"朱红色的凤形发钗。","line":1,"start":11,"end":13,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"斜松","explanation":"斜斜插着、有些松动的样子。","line":1,"start":13,"end":15,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"双弯浅碧","explanation":"指眉毛画成浅碧色的两道弯，形如柳叶。","line":1,"start":21,"end":25,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"樱桃一颗娇红","explanation":"形容嘴唇涂得如樱桃般娇艳红润。","line":1,"start":29,"end":35,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"秋水","explanation":"形容女子眼波如秋天的水一般澄澈灵动。","line":1,"start":41,"end":43,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"连花","explanation":"通“莲花”，形容面容如莲花般清丽。","line":1,"start":46,"end":48,"source_text":"鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。"},{"word":"鸾钗","explanation":"雕有鸾鸟形状的发钗。蹀躞（dié xiè）：原指小步行走，此处形容钗上的花饰随动作轻轻颤动的样子。","line":2,"start":0,"end":2,"source_text":"鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。"},{"word":"凤翘","explanation":"凤形的翘头首饰。","line":2,"start":8,"end":10,"source_text":"鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。"},{"word":"玲珑","explanation":"明澈精巧的样子。","line":2,"start":13,"end":15,"source_text":"鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。"},{"word":"胭脂蜡","explanation":"凝固如蜡状的胭脂。","line":2,"start":16,"end":19,"source_text":"鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。"},{"word":"锦犀盒","explanation":"用犀角装饰、织锦包裹的盒子，用来盛放胭脂。","line":2,"start":21,"end":24,"source_text":"鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。"},{"word":"蔷薇露","explanation":"古代女子护肤用的香水，以蔷薇花蒸馏制成。","line":2,"start":25,"end":28,"source_text":"鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。"},{"word":"玻璃瓮","explanation":"玻璃制的小口大腹容器。","line":2,"start":30,"end":33,"source_text":"鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。"},{"word":"艳质","explanation":"艳丽的姿容。","line":3,"start":3,"end":5,"source_text":"端详了艳质，出落着春工。"},{"word":"出落","explanation":"长成，显现。","line":3,"start":6,"end":8,"source_text":"端详了艳质，出落着春工。"},{"word":"春工","explanation":"春日造化之工，此处形容女子的美貌是天地春日造化所成。","line":3,"start":9,"end":11,"source_text":"端详了艳质，出落着春工。"}]'::jsonb WHERE id='d7fe42c9-3cea-432e-9e6a-681a3ed974b4' AND content='绣帏春重，趁东风培养出牡丹丛。流苏斗帐，龟甲屏风。七宝妆奁明彩钿，一帘香雾袅薰笼；慢卷起金花孔雀，锦屏开绿水芙蓉。
鸦翅袒金蝉半妥，翠云偏朱凤斜松，眉儿扫杨柳双弯浅碧，口儿点樱桃一颗娇红；眼如珠光摇秋水，脸如连花笑春风。
鸾钗插花枝蹀躞，凤翘悬珠翠玲珑；胭脂蜡红腻锦犀盒，蔷薇露滴注玻璃瓮。
端详了艳质，出落着春工。' AND annotation='①混江龙：元曲曲牌名，属北曲仙吕宫，句式多为长短错落，适宜铺陈描摹。
②绣帏：绣花的帐幔，代指女子闺房。流苏斗帐：装饰有穗状流苏的小方帐，为古代贵族女子的卧具。
③龟甲屏风：用龟甲纹装饰的屏风，亦有说以龟甲镶嵌为饰，是名贵的室内陈设。
④七宝妆奁：镶嵌多种珍宝的女子梳妆匣。彩钿：镶嵌螺贝等宝物的花饰，女子头饰的一种。
⑤薰笼：覆盖在香炉上的笼具，用来熏香衣被，此处写香雾从薰笼升起弥漫一帘。
⑥金花孔雀：指绣有孔雀、饰有金花的门帘。绿水芙蓉：指绘有绿水、芙蓉图案的锦制屏风。
⑦鸦翅：形容女子乌黑鬓发如同鸦鸟的翅膀。金蝉：古代女子的金属蝉形头饰。妥：妥帖，此处指头饰半垂的状态。
⑧翠云：形容女子头发像翠色云团。朱凤：朱红色的凤形发钗。斜松：斜斜插着、有些松动的样子。
⑨双弯浅碧：指眉毛画成浅碧色的两道弯，形如柳叶。樱桃一颗娇红：形容嘴唇涂得如樱桃般娇艳红润。
⑩秋水：形容女子眼波如秋天的水一般澄澈灵动。连花：通“莲花”，形容面容如莲花般清丽。
⑪鸾钗：雕有鸾鸟形状的发钗。蹀躞（dié xiè）：原指小步行走，此处形容钗上的花饰随动作轻轻颤动的样子。
⑫凤翘：凤形的翘头首饰。玲珑：明澈精巧的样子。
⑬胭脂蜡：凝固如蜡状的胭脂。锦犀盒：用犀角装饰、织锦包裹的盒子，用来盛放胭脂。
⑭蔷薇露：古代女子护肤用的香水，以蔷薇花蒸馏制成。玻璃瓮：玻璃制的小口大腹容器。
⑮艳质：艳丽的姿容。出落：长成，显现。春工：春日造化之工，此处形容女子的美貌是天地春日造化所成。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"檀栾","explanation":"形容竹之秀美貌，此处代指斤竹岭上的竹林。","line":0,"start":0,"end":2,"source_text":"檀栾暎空曲，青翠漾涟漪。"},{"word":"空曲","explanation":"空山曲折的坳谷。","line":0,"start":3,"end":5,"source_text":"檀栾暎空曲，青翠漾涟漪。"},{"word":"青翠","explanation":"指竹子苍青翠绿的色泽，也指竹子映在水中的倒影。","line":0,"start":6,"end":8,"source_text":"檀栾暎空曲，青翠漾涟漪。"},{"word":"漾涟漪","explanation":"指竹影在水波里荡漾，泛起细碎波纹。","line":0,"start":8,"end":11,"source_text":"檀栾暎空曲，青翠漾涟漪。"},{"word":"商山路","explanation":"通往商山的路径，商山是秦汉间“商山四皓”隐居之地，此处代指通往隐居之所的道路。","line":1,"start":2,"end":5,"source_text":"暗入商山路，樵人不可知。"},{"word":"樵人","explanation":"砍柴的人。","line":1,"start":6,"end":8,"source_text":"暗入商山路，樵人不可知。"}]'::jsonb WHERE id='d8f87946-f6dc-4a17-8b77-24365cfd3e0f' AND content='檀栾暎空曲，青翠漾涟漪。
暗入商山路，樵人不可知。' AND annotation='①檀栾：形容竹之秀美貌，此处代指斤竹岭上的竹林。空曲：空山曲折的坳谷。
②青翠：指竹子苍青翠绿的色泽，也指竹子映在水中的倒影。漾涟漪：指竹影在水波里荡漾，泛起细碎波纹。
③商山路：通往商山的路径，商山是秦汉间“商山四皓”隐居之地，此处代指通往隐居之所的道路。
④樵人：砍柴的人。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"双头凤","explanation":"指女子头上插的双头凤形发簪，推整双头凤是含羞时借整理首饰掩饰情态的动作。","line":0,"start":13,"end":16,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"柳情花意","explanation":"以春日柳柔花媚的情态，比喻女子柔媚含情的风姿。","line":0,"start":17,"end":21,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"钿窝儿","explanation":"女子面颊上贴花钿的地方，也指酒窝。","line":0,"start":25,"end":28,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"晓翠","explanation":"即翡翠钿饰，一说指清早沾上的鬓边翠色。","line":0,"start":30,"end":32,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"腮斗儿","explanation":"腮帮子，俗称腮颊。","line":0,"start":33,"end":36,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"春红","explanation":"指含羞时泛起的娇红色晕。","line":0,"start":38,"end":40,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"风月约","explanation":"均为古时男女幽会的隐语，化用宋玉《高唐赋》巫山神女“旦为朝云，暮为行雨”的典故。","line":0,"start":44,"end":47,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"雨云踪","explanation":"均为古时男女幽会的隐语，化用宋玉《高唐赋》巫山神女“旦为朝云，暮为行雨”的典故。","line":0,"start":51,"end":54,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"},{"word":"出落","explanation":"显现、表露之意。","line":0,"start":48,"end":50,"source_text":"脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。"}]'::jsonb WHERE id='d93aa196-79be-4b20-a5eb-015dfb1a255a' AND content='脸霞红，眼波横。见人羞推整双头凤。柳情花意媚东风。钿窝儿里粘晓翠，腮斗儿上晕春红。包藏着风月约，出落着雨云踪。' AND annotation='①金盏儿：曲牌名，又名“醉金盏”，属北曲仙吕宫，句式为三、三、七、五、七、五、七、七，共八句。
②双头凤：指女子头上插的双头凤形发簪，推整双头凤是含羞时借整理首饰掩饰情态的动作。
③柳情花意：以春日柳柔花媚的情态，比喻女子柔媚含情的风姿。
④钿窝儿：女子面颊上贴花钿的地方，也指酒窝。晓翠：即翡翠钿饰，一说指清早沾上的鬓边翠色。
⑤腮斗儿：腮帮子，俗称腮颊。春红：指含羞时泛起的娇红色晕。
⑥风月约、雨云踪：均为古时男女幽会的隐语，化用宋玉《高唐赋》巫山神女“旦为朝云，暮为行雨”的典故。
⑦出落：显现、表露之意。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"荼縻","explanation":"即荼蘼，晚春开花的落叶灌木，花色多白或带黄晕，是春季最后盛放的花之一，古人有“开到荼蘼花事了”之说。","line":0,"start":2,"end":4,"source_text":"最好荼縻白间黄。"},{"word":"消他","explanation":"消受得、引得。","line":1,"start":0,"end":2,"source_text":"消他蜂蝶采花忙。"},{"word":"红粉","explanation":"此处代指年轻女子，一说指春日残落的各色花卉。","line":2,"start":2,"end":4,"source_text":"春残红粉厌梳妆。"},{"word":"毕卓正思身夜瓮","explanation":"用晋代毕卓的典故，毕卓嗜酒，曾言“得酒满数百斛船，四时甘味置两头，右手持酒杯，左手持蟹螯，拍浮酒船中，便足了一生矣”，此处化用其醉卧酒瓮旁的典故，喻沉醉于荼蘼香气的状态。","line":3,"start":0,"end":7,"source_text":"毕卓正思身夜瓮，刘章底用令秋霜。"},{"word":"刘章底用令秋霜","explanation":"用西汉刘章的典故，刘章为朱虚侯，曾在吕后酒宴上以军法行酒，杀逃酒者，此处反用其意，说根本不需要像刘章行酒令那样用严令催饮，花香已足够醉人。","line":3,"start":8,"end":15,"source_text":"毕卓正思身夜瓮，刘章底用令秋霜。"},{"word":"底用","explanation":"何用、何须。","line":3,"start":10,"end":12,"source_text":"毕卓正思身夜瓮，刘章底用令秋霜。"},{"word":"帏枕","explanation":"帏帐与枕席。","line":4,"start":2,"end":4,"source_text":"今宵帏枕十分香。"}]'::jsonb WHERE id='da008b14-7558-435e-9fd1-32dce37d8327' AND content='最好荼縻白间黄。
消他蜂蝶采花忙。
春残红粉厌梳妆。
毕卓正思身夜瓮，刘章底用令秋霜。
今宵帏枕十分香。' AND annotation='①荼縻：即荼蘼，晚春开花的落叶灌木，花色多白或带黄晕，是春季最后盛放的花之一，古人有“开到荼蘼花事了”之说。
②消他：消受得、引得。
③红粉：此处代指年轻女子，一说指春日残落的各色花卉。
④毕卓正思身夜瓮：用晋代毕卓的典故，毕卓嗜酒，曾言“得酒满数百斛船，四时甘味置两头，右手持酒杯，左手持蟹螯，拍浮酒船中，便足了一生矣”，此处化用其醉卧酒瓮旁的典故，喻沉醉于荼蘼香气的状态。
⑤刘章底用令秋霜：用西汉刘章的典故，刘章为朱虚侯，曾在吕后酒宴上以军法行酒，杀逃酒者，此处反用其意，说根本不需要像刘章行酒令那样用严令催饮，花香已足够醉人。底用：何用、何须。
⑥帏枕：帏帐与枕席。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"伫倚","explanation":"长久地倚立。","line":0,"start":0,"end":2,"source_text":"伫倚危楼风细细。"},{"word":"危楼","explanation":"高楼。","line":0,"start":2,"end":4,"source_text":"伫倚危楼风细细。"},{"word":"望极","explanation":"极目远望。","line":1,"start":0,"end":2,"source_text":"望极春愁，黯黯生天际。"},{"word":"黯黯","explanation":"形容景色昏暗，也映出心绪低沉。","line":1,"start":5,"end":7,"source_text":"望极春愁，黯黯生天际。"},{"word":"残照","explanation":"将落未落的夕阳。","line":2,"start":4,"end":6,"source_text":"草色烟光残照里。"},{"word":"凭阑","explanation":"倚着栏杆。","line":3,"start":4,"end":6,"source_text":"无言谁会凭阑意。"},{"word":"拟把","explanation":"打算借着。","line":4,"start":0,"end":2,"source_text":"拟把疏狂图一醉。"},{"word":"疏狂","explanation":"放纵不拘，指纵酒遣怀。","line":4,"start":2,"end":4,"source_text":"拟把疏狂图一醉。"},{"word":"强乐","explanation":"勉强作乐。","line":5,"start":5,"end":7,"source_text":"对酒当歌，强乐还无味。"},{"word":"衣带渐宽","explanation":"衣带越来越松，写人因相思日渐消瘦。","line":6,"start":0,"end":4,"source_text":"衣带渐宽终不悔。"},{"word":"伊","explanation":"她或他，指心中所思之人。","line":7,"start":1,"end":2,"source_text":"为伊消得人憔悴。"}]'::jsonb WHERE id='df844ca7-6ad7-484d-accc-b450863ccd11' AND content='伫倚危楼风细细。
望极春愁，黯黯生天际。
草色烟光残照里。
无言谁会凭阑意。
拟把疏狂图一醉。
对酒当歌，强乐还无味。
衣带渐宽终不悔。
为伊消得人憔悴。' AND annotation='伫倚：长久地倚立。危楼：高楼。
望极：极目远望。黯黯：形容景色昏暗，也映出心绪低沉。
残照：将落未落的夕阳。凭阑：倚着栏杆。
拟把：打算借着。疏狂：放纵不拘，指纵酒遣怀。强乐：勉强作乐。
衣带渐宽：衣带越来越松，写人因相思日渐消瘦。伊：她或他，指心中所思之人。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"回雪韦娘","explanation":"用曹植“流风之回雪”及“杜韦娘”事，指舞姿曼妙的女伎。","line":5,"start":24,"end":28,"source_text":"爱共寝花间锦鸠，恨孤眠水上白鸥。月宵花昼，大筵排回雪韦娘，小酌会窃香韩寿。举觞红袖，玉纤横管，银甲调筝，酒令诗筹。曲成诗就，韵协声律，情动魂消，腹稿冥搜，美恩当受。水仙山鬼，月妹花妖，如还得遇，不许干休。会埋伏未尝泄漏。"},{"word":"窃香韩寿","explanation":"用韩寿窃香与贾充女私通之典，代指风流才俊情郎。","line":5,"start":32,"end":36,"source_text":"爱共寝花间锦鸠，恨孤眠水上白鸥。月宵花昼，大筵排回雪韦娘，小酌会窃香韩寿。举觞红袖，玉纤横管，银甲调筝，酒令诗筹。曲成诗就，韵协声律，情动魂消，腹稿冥搜，美恩当受。水仙山鬼，月妹花妖，如还得遇，不许干休。会埋伏未尝泄漏。"},{"word":"腹稿冥搜","explanation":"暗中反复构思，打好腹稿（借以自嘲思虑计算之深）。","line":5,"start":72,"end":76,"source_text":"爱共寝花间锦鸠，恨孤眠水上白鸥。月宵花昼，大筵排回雪韦娘，小酌会窃香韩寿。举觞红袖，玉纤横管，银甲调筝，酒令诗筹。曲成诗就，韵协声律，情动魂消，腹稿冥搜，美恩当受。水仙山鬼，月妹花妖，如还得遇，不许干休。会埋伏未尝泄漏。"},{"word":"绿肥红瘦","explanation":"化李清照《如梦令》语，指花残春去。","line":7,"start":13,"end":17,"source_text":"群芳会首，繁英故友。梦回时绿肥红瘦，荣华过可见疏薄，财物广始知亲厚。慕新思旧，簪遗佩解，镜破钗分，蜂妒蝶羞。恶缘难救，痼疾常发，业贯将盈，努力呈头。冷餐重馏，口刀舌剑，吻槊唇枪，独攻决胜，混战无忧，不到得落人奸彀。"},{"word":"痼疾","explanation":"久难治愈的嗜好，此指沉湎风月的积习。","line":7,"start":59,"end":61,"source_text":"群芳会首，繁英故友。梦回时绿肥红瘦，荣华过可见疏薄，财物广始知亲厚。慕新思旧，簪遗佩解，镜破钗分，蜂妒蝶羞。恶缘难救，痼疾常发，业贯将盈，努力呈头。冷餐重馏，口刀舌剑，吻槊唇枪，独攻决胜，混战无忧，不到得落人奸彀。"},{"word":"业贯将盈","explanation":"业障积满、受报将尽，为自谑语。","line":7,"start":64,"end":68,"source_text":"群芳会首，繁英故友。梦回时绿肥红瘦，荣华过可见疏薄，财物广始知亲厚。慕新思旧，簪遗佩解，镜破钗分，蜂妒蝶羞。恶缘难救，痼疾常发，业贯将盈，努力呈头。冷餐重馏，口刀舌剑，吻槊唇枪，独攻决胜，混战无忧，不到得落人奸彀。"},{"word":"冷餐重馏","explanation":"冷饭热粥、粗茶淡饭。","line":7,"start":74,"end":78,"source_text":"群芳会首，繁英故友。梦回时绿肥红瘦，荣华过可见疏薄，财物广始知亲厚。慕新思旧，簪遗佩解，镜破钗分，蜂妒蝶羞。恶缘难救，痼疾常发，业贯将盈，努力呈头。冷餐重馏，口刀舌剑，吻槊唇枪，独攻决胜，混战无忧，不到得落人奸彀。"},{"word":"吻槊唇枪","explanation":"唇舌如矛如枪，指打趣拌嘴。","line":7,"start":84,"end":88,"source_text":"群芳会首，繁英故友。梦回时绿肥红瘦，荣华过可见疏薄，财物广始知亲厚。慕新思旧，簪遗佩解，镜破钗分，蜂妒蝶羞。恶缘难救，痼疾常发，业贯将盈，努力呈头。冷餐重馏，口刀舌剑，吻槊唇枪，独攻决胜，混战无忧，不到得落人奸彀。"},{"word":"孙吴","explanation":"孙武、吴起，古代用兵大家。","line":9,"start":24,"end":26,"source_text":"展放征旗任谁走，庙算神谟必应口。一管笔在手，敢搦孙吴兵斗。"},{"word":"搦","explanation":"挑战。","line":9,"start":23,"end":24,"source_text":"展放征旗任谁走，庙算神谟必应口。一管笔在手，敢搦孙吴兵斗。"}]'::jsonb WHERE id='dff4fa7f-3e67-4bf5-94c9-56be4cc3bb86' AND content='〔青杏子〕
花月酒家楼，可追欢亦可悲秋。悲欢聚散为常事，明眸皓齿，歌莺舞燕，各逞温柔。
〔幺篇〕
人俊惜风流，欠前生酒病花愁。尚还不彻相思债，携云挈雨，批风切月，到处绸缪。
〔催拍子〕
爱共寝花间锦鸠，恨孤眠水上白鸥。月宵花昼，大筵排回雪韦娘，小酌会窃香韩寿。举觞红袖，玉纤横管，银甲调筝，酒令诗筹。曲成诗就，韵协声律，情动魂消，腹稿冥搜，美恩当受。水仙山鬼，月妹花妖，如还得遇，不许干休。会埋伏未尝泄漏。
〔幺篇〕
群芳会首，繁英故友。梦回时绿肥红瘦，荣华过可见疏薄，财物广始知亲厚。慕新思旧，簪遗佩解，镜破钗分，蜂妒蝶羞。恶缘难救，痼疾常发，业贯将盈，努力呈头。冷餐重馏，口刀舌剑，吻槊唇枪，独攻决胜，混战无忧，不到得落人奸彀。
〔尾〕
展放征旗任谁走，庙算神谟必应口。一管笔在手，敢搦孙吴兵斗。' AND annotation='①回雪韦娘：用曹植“流风之回雪”及“杜韦娘”事，指舞姿曼妙的女伎。
②窃香韩寿：用韩寿窃香与贾充女私通之典，代指风流才俊情郎。
③腹稿冥搜：暗中反复构思，打好腹稿（借以自嘲思虑计算之深）。
④绿肥红瘦：化李清照《如梦令》语，指花残春去。
⑤痼疾：久难治愈的嗜好，此指沉湎风月的积习。业贯将盈：业障积满、受报将尽，为自谑语。
⑥冷餐重馏：冷饭热粥、粗茶淡饭。吻槊唇枪：唇舌如矛如枪，指打趣拌嘴。
⑦孙吴：孙武、吴起，古代用兵大家。搦：挑战。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"心丧","explanation":"古时弟子为老师守丧，不穿丧服，只在心中哀悼，称心丧。","line":0,"start":5,"end":7,"source_text":"三年谁与共心丧，"},{"word":"摩挲","explanation":"用手轻轻抚摸。","line":1,"start":2,"end":4,"source_text":"旧物摩挲泪几行。"},{"word":"绛幄","explanation":"绛红色的帐幔，此处指书房的帷帘。","line":2,"start":5,"end":7,"source_text":"夜冷有风开绛幄，"},{"word":"尘梁","explanation":"世俗的桥梁，此处指人世、阳间。","line":3,"start":5,"end":7,"source_text":"水深无梦到尘梁。"},{"word":"残煤","explanation":"残剩的墨痕，煤是墨的别称。","line":4,"start":0,"end":2,"source_text":"残煤半落加餐字，"},{"word":"加餐字","explanation":"指邵叔宀生前叮嘱自己多吃饭保重身体的手书内容。","line":4,"start":4,"end":7,"source_text":"残煤半落加餐字，"},{"word":"细楷","explanation":"小楷，此处指老师生前亲笔所写的字迹。","line":5,"start":0,"end":2,"source_text":"细楷曾传养病方。"},{"word":"夜台","explanation":"指坟墓，阴间，因坟墓中昏暗不见光明，故称。","line":6,"start":2,"end":4,"source_text":"料得夜台闻太息，"},{"word":"徬徨","explanation":"形容心神不安、徘徊无措的样子。","line":7,"start":5,"end":7,"source_text":"此时忆我定徬徨。"}]'::jsonb WHERE id='e0f5794d-6bdb-4ee6-8981-caabaa616970' AND content='三年谁与共心丧，
旧物摩挲泪几行。
夜冷有风开绛幄，
水深无梦到尘梁。
残煤半落加餐字，
细楷曾传养病方。
料得夜台闻太息，
此时忆我定徬徨。' AND annotation='①心丧：古时弟子为老师守丧，不穿丧服，只在心中哀悼，称心丧。
②摩挲：用手轻轻抚摸。
③绛幄：绛红色的帐幔，此处指书房的帷帘。
④尘梁：世俗的桥梁，此处指人世、阳间。
⑤残煤：残剩的墨痕，煤是墨的别称。加餐字：指邵叔宀生前叮嘱自己多吃饭保重身体的手书内容。
⑥细楷：小楷，此处指老师生前亲笔所写的字迹。
⑦夜台：指坟墓，阴间，因坟墓中昏暗不见光明，故称。
⑧徬徨：形容心神不安、徘徊无措的样子。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"皇英","explanation":"尧帝的两个女儿娥皇、女英，同为舜帝的妃子。","line":0,"start":6,"end":8,"source_text":"远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。"},{"word":"洞庭","explanation":"洞庭湖与潇水、湘水，传说舜南巡死于苍梧，二妃追至湘水一带，投水而死，成为湘水女神。","line":0,"start":14,"end":16,"source_text":"远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。"},{"word":"潇湘","explanation":"洞庭湖与潇水、湘水，传说舜南巡死于苍梧，二妃追至湘水一带，投水而死，成为湘水女神。","line":0,"start":19,"end":21,"source_text":"远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。"},{"word":"皇穹","explanation":"苍天，此处暗指当朝君主。","line":3,"start":8,"end":10,"source_text":"我纵言之将何补，皇穹窃恐不照余之忠诚。"},{"word":"禅禹","explanation":"指尧舜将帝位禅让给大禹。","line":4,"start":13,"end":15,"source_text":"雷冯冯兮欲吼怒，尧舜当之亦禅禹。"},{"word":"九疑","explanation":"即九疑山，在今湖南宁远，传说舜葬于此，山形相似，难以分辨具体葬处。","line":6,"start":10,"end":12,"source_text":"或云尧幽囚，舜野死，九疑联緜皆相似，重瞳孤坟竟何是。"},{"word":"重瞳","explanation":"指舜，传说舜眼中有两个瞳孔。","line":6,"start":18,"end":20,"source_text":"或云尧幽囚，舜野死，九疑联緜皆相似，重瞳孤坟竟何是。"},{"word":"帝子","explanation":"指娥皇、女英。","line":7,"start":0,"end":2,"source_text":"帝子泣兮绿云间，随风波兮去无还。"},{"word":"竹上之泪","explanation":"指湘妃竹，传说二妃哭舜，泪水染竹成斑，故称斑竹、湘妃竹。","line":9,"start":8,"end":12,"source_text":"苍梧山崩湘水绝，竹上之泪乃可灭。"}]'::jsonb WHERE id='e1c4ea9a-eccb-4329-9905-519b7232eb0c' AND content='远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。
海水直下万里深，谁人不言此离苦。
日惨惨兮云冥冥，猩猩啼烟兮鬼啸雨。
我纵言之将何补，皇穹窃恐不照余之忠诚。
雷冯冯兮欲吼怒，尧舜当之亦禅禹。
君失臣兮龙为鱼，权归臣兮鼠变虎。
或云尧幽囚，舜野死，九疑联緜皆相似，重瞳孤坟竟何是。
帝子泣兮绿云间，随风波兮去无还。
恸哭兮远望，见苍梧之深山。
苍梧山崩湘水绝，竹上之泪乃可灭。' AND annotation='①皇英：尧帝的两个女儿娥皇、女英，同为舜帝的妃子。
②洞庭、潇湘：洞庭湖与潇水、湘水，传说舜南巡死于苍梧，二妃追至湘水一带，投水而死，成为湘水女神。
③皇穹：苍天，此处暗指当朝君主。
④冯冯（píng píng）：形容雷声盛大的样子。
⑤禅禹：指尧舜将帝位禅让给大禹。
⑥尧幽囚，舜野死：古史传说尧晚年被舜囚禁，舜南巡时死于苍梧之野。
⑦九疑：即九疑山，在今湖南宁远，传说舜葬于此，山形相似，难以分辨具体葬处。
⑧重瞳：指舜，传说舜眼中有两个瞳孔。
⑨帝子：指娥皇、女英。
⑩竹上之泪：指湘妃竹，传说二妃哭舜，泪水染竹成斑，故称斑竹、湘妃竹。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"鸾旗","explanation":"帝王仪仗中的旗帜，上绣鸾鸟图案。","line":0,"start":0,"end":2,"source_text":"鸾旗掣曳拂空回，羽骑骖驔蹑景来。"},{"word":"掣曳","explanation":"飘扬摇曳的样子。","line":0,"start":2,"end":4,"source_text":"鸾旗掣曳拂空回，羽骑骖驔蹑景来。"},{"word":"拂空回","explanation":"拂过天空，来回飘动。","line":0,"start":4,"end":7,"source_text":"鸾旗掣曳拂空回，羽骑骖驔蹑景来。"},{"word":"羽骑","explanation":"皇帝的羽林禁军骑兵。骖驔（cān diàn）：形容马匹奔跑腾跃的样子。蹑景（niè yǐng）：追赶日影，形容马行速度极快，“景”同“影”。","line":0,"start":8,"end":10,"source_text":"鸾旗掣曳拂空回，羽骑骖驔蹑景来。"},{"word":"隐隐","explanation":"隐约、模糊的样子。","line":1,"start":0,"end":2,"source_text":"隐隐骊山云外耸，迢迢御帐日边开。"},{"word":"骊山","explanation":"山名，在今陕西临潼，新丰温泉宫（即华清宫）坐落于此。","line":1,"start":2,"end":4,"source_text":"隐隐骊山云外耸，迢迢御帐日边开。"},{"word":"耸","explanation":"高耸。","line":1,"start":6,"end":7,"source_text":"隐隐骊山云外耸，迢迢御帐日边开。"},{"word":"迢迢","explanation":"遥远的样子。","line":1,"start":8,"end":10,"source_text":"隐隐骊山云外耸，迢迢御帐日边开。"},{"word":"御帐","explanation":"皇帝出行时用的帐幕。","line":1,"start":10,"end":12,"source_text":"隐隐骊山云外耸，迢迢御帐日边开。"},{"word":"日边","explanation":"指皇帝身边，也对应帐幕高悬仿佛接近日边的视觉效果。","line":1,"start":12,"end":14,"source_text":"隐隐骊山云外耸，迢迢御帐日边开。"},{"word":"开","explanation":"张开、陈设。","line":1,"start":14,"end":15,"source_text":"隐隐骊山云外耸，迢迢御帐日边开。"}]'::jsonb WHERE id='e3a926dd-800c-4378-aad3-ecc64d1f4e44' AND content='鸾旗掣曳拂空回，羽骑骖驔蹑景来。
隐隐骊山云外耸，迢迢御帐日边开。' AND annotation='①鸾旗：帝王仪仗中的旗帜，上绣鸾鸟图案。掣曳：飘扬摇曳的样子。拂空回：拂过天空，来回飘动。
②羽骑：皇帝的羽林禁军骑兵。骖驔（cān diàn）：形容马匹奔跑腾跃的样子。蹑景（niè yǐng）：追赶日影，形容马行速度极快，“景”同“影”。
③隐隐：隐约、模糊的样子。骊山：山名，在今陕西临潼，新丰温泉宫（即华清宫）坐落于此。耸：高耸。
④迢迢：遥远的样子。御帐：皇帝出行时用的帐幕。日边：指皇帝身边，也对应帐幕高悬仿佛接近日边的视觉效果。开：张开、陈设。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"那咤令","explanation":"首折正旦樊素所唱套曲曲牌。","line":18,"start":1,"end":4,"source_text":"【那咤令】"},{"word":"南容","explanation":"古之美妇，此处以小蛮小字作比。","line":41,"start":6,"end":8,"source_text":"寂寂深闺𥚃。南容苦夜长。"},{"word":"粉郎","explanation":"指姓白的少年（借\"傅粉何郎\"之典）。","line":42,"start":0,"end":2,"source_text":"粉郎休易别。遗赠紫香囊。"},{"word":"南容","explanation":"古之美妇，此处以小蛮小字作比。","line":43,"start":121,"end":123,"source_text":"原来这香囊儿是小姐故意遗下与小生的。我仔细详解一遍咱。上面这同心结子。他道与我同心合意。中间是一把莲。莲心为藕。他要与小生成其配偶。下面有两个交颈鸳鸯儿。他意中与小生同衾共枕。遂成交颈。这一首诗中。说道寂寂深闺𥚃。他道在深闺。无人知道的去处。南容苦夜长。南容者。古之美妇也。为甚比他做为南容。为他小字小蛮。故比南容也。粉郎休易别。为小生姓白。故说粉郎。休易别。为我累次要辞夫人回家去。他教我休便去了。遗赠紫香囊。故意留与小生为信物。原来小姐向小生却如此留意。从今日起头。那有心弹琴讲书。只索每日晨参暮礼。将此香囊供养者。香囊呵。少不的为你害杀小生也。（诗云）"},{"word":"南容","explanation":"古之美妇，此处以小蛮小字作比。","line":43,"start":127,"end":129,"source_text":"原来这香囊儿是小姐故意遗下与小生的。我仔细详解一遍咱。上面这同心结子。他道与我同心合意。中间是一把莲。莲心为藕。他要与小生成其配偶。下面有两个交颈鸳鸯儿。他意中与小生同衾共枕。遂成交颈。这一首诗中。说道寂寂深闺𥚃。他道在深闺。无人知道的去处。南容苦夜长。南容者。古之美妇也。为甚比他做为南容。为他小字小蛮。故比南容也。粉郎休易别。为小生姓白。故说粉郎。休易别。为我累次要辞夫人回家去。他教我休便去了。遗赠紫香囊。故意留与小生为信物。原来小姐向小生却如此留意。从今日起头。那有心弹琴讲书。只索每日晨参暮礼。将此香囊供养者。香囊呵。少不的为你害杀小生也。（诗云）"},{"word":"南容","explanation":"古之美妇，此处以小蛮小字作比。","line":43,"start":143,"end":145,"source_text":"原来这香囊儿是小姐故意遗下与小生的。我仔细详解一遍咱。上面这同心结子。他道与我同心合意。中间是一把莲。莲心为藕。他要与小生成其配偶。下面有两个交颈鸳鸯儿。他意中与小生同衾共枕。遂成交颈。这一首诗中。说道寂寂深闺𥚃。他道在深闺。无人知道的去处。南容苦夜长。南容者。古之美妇也。为甚比他做为南容。为他小字小蛮。故比南容也。粉郎休易别。为小生姓白。故说粉郎。休易别。为我累次要辞夫人回家去。他教我休便去了。遗赠紫香囊。故意留与小生为信物。原来小姐向小生却如此留意。从今日起头。那有心弹琴讲书。只索每日晨参暮礼。将此香囊供养者。香囊呵。少不的为你害杀小生也。（诗云）"},{"word":"南容","explanation":"古之美妇，此处以小蛮小字作比。","line":43,"start":155,"end":157,"source_text":"原来这香囊儿是小姐故意遗下与小生的。我仔细详解一遍咱。上面这同心结子。他道与我同心合意。中间是一把莲。莲心为藕。他要与小生成其配偶。下面有两个交颈鸳鸯儿。他意中与小生同衾共枕。遂成交颈。这一首诗中。说道寂寂深闺𥚃。他道在深闺。无人知道的去处。南容苦夜长。南容者。古之美妇也。为甚比他做为南容。为他小字小蛮。故比南容也。粉郎休易别。为小生姓白。故说粉郎。休易别。为我累次要辞夫人回家去。他教我休便去了。遗赠紫香囊。故意留与小生为信物。原来小姐向小生却如此留意。从今日起头。那有心弹琴讲书。只索每日晨参暮礼。将此香囊供养者。香囊呵。少不的为你害杀小生也。（诗云）"},{"word":"粉郎","explanation":"指姓白的少年（借\"傅粉何郎\"之典）。","line":43,"start":159,"end":161,"source_text":"原来这香囊儿是小姐故意遗下与小生的。我仔细详解一遍咱。上面这同心结子。他道与我同心合意。中间是一把莲。莲心为藕。他要与小生成其配偶。下面有两个交颈鸳鸯儿。他意中与小生同衾共枕。遂成交颈。这一首诗中。说道寂寂深闺𥚃。他道在深闺。无人知道的去处。南容苦夜长。南容者。古之美妇也。为甚比他做为南容。为他小字小蛮。故比南容也。粉郎休易别。为小生姓白。故说粉郎。休易别。为我累次要辞夫人回家去。他教我休便去了。遗赠紫香囊。故意留与小生为信物。原来小姐向小生却如此留意。从今日起头。那有心弹琴讲书。只索每日晨参暮礼。将此香囊供养者。香囊呵。少不的为你害杀小生也。（诗云）"},{"word":"粉郎","explanation":"指姓白的少年（借\"傅粉何郎\"之典）。","line":43,"start":173,"end":175,"source_text":"原来这香囊儿是小姐故意遗下与小生的。我仔细详解一遍咱。上面这同心结子。他道与我同心合意。中间是一把莲。莲心为藕。他要与小生成其配偶。下面有两个交颈鸳鸯儿。他意中与小生同衾共枕。遂成交颈。这一首诗中。说道寂寂深闺𥚃。他道在深闺。无人知道的去处。南容苦夜长。南容者。古之美妇也。为甚比他做为南容。为他小字小蛮。故比南容也。粉郎休易别。为小生姓白。故说粉郎。休易别。为我累次要辞夫人回家去。他教我休便去了。遗赠紫香囊。故意留与小生为信物。原来小姐向小生却如此留意。从今日起头。那有心弹琴讲书。只索每日晨参暮礼。将此香囊供养者。香囊呵。少不的为你害杀小生也。（诗云）"}]'::jsonb WHERE id='e684259f-37c4-45e8-b564-6fd2e05146a2' AND content='（白敏中上诗云）
寂寞琴书冷竹床。砚池春煖墨痕香。
男儿未遂风流志。剔尽青灯苦夜长。
自从昨日在绿野堂上。见了夫人。不知主何意。将亲事全然不题。则说着小姐拜哥哥。被我回言道。先相国在日。并不曾言兄妹之礼。况兼小子见将着玉带为信物。夫人急忙回言。秀才是甚休题。则说着孩儿拜了哥哥者。我不免受了小姐的礼。我见小姐容仪。远视而威。近视而美。端的可为贵人之妻。老子云。不见可欲。使心不乱。信有之也。我当初不见也罢了。自见小姐之后。朝则忘餐。夜则废寝。其心飘飘然如有所失。小子安歇在万卷堂上。夫人相待虽厚。终非小生本愿。区区岂为餔啜而来。小生累次教人问这亲事。夫人回言。终不还个明白。如之奈何。恰才又使院公去。说小生要辞夫人。回家拜扫去。看他有甚的言语。我再做商量者。（下）（旦儿上云）好闷倦人也呵。我常记的。我父亲临命终时。对我母亲说。我征淮西。被贼围困。刃将及首。皆赖白参军挺身杀退贼兵。救我一命。因此将女孩儿许与参军之子白敏中为妻。就将玉带一条为信。兀那时节。我才十二三岁也。父亲遗言。明白如此。在后不想白氏音问不通。以此不曾成就这亲事。我前日和樊素在母亲行讲书。院公报道白敏中来了。我欲回避。不知母亲主何意。却着我拜他做哥哥。那生回言道。先相国存日。并不曾言兄妹之礼。母亲便道。秀才是甚休题。我一见那生。眉疎目秀。容止可观。年方弱冠。才名已遍天下。若进取功名。何所不至。好着我放心不下。此非有甚狂意。乃前程所关。况兼先人之语。铭注肺腑。万一背却前言。俺母亲有何面目见先人于九泉之下乎。近日又听的那生。要辞夫人回家拜扫去。我仔细寻思来。不争他回家去呵。路途遥远。关山阻隔。这亲事几时得就。我两日前。悄悄的绣下一个香囊儿。上面有一首诗。诗中多有包含的意思。我又不敢使人送去。惟有伴我读书的樊素。与我不离半步儿。那妮子生的聪明晓事。诸余可爱。则是性儿飘逸些。今这事他若知道呵。便说的一家都知道了。怎生是好。这两日樊素累累的对我说道。姐姐。后花园中看花去来。被我骂将去了。今夜点上灯。不做生活。和他讲书。若得他开口呵。我便和他后花园中看花去。我将这香囊儿。撇在那生书房门首。若是那生拾得。看了这诗呵。便知道我的意思。倘别人拾了呵。我则推不知。非是我心多。岂不闻人无远虑。必有近忧。这早晚樊素敢待来也。（正旦上云）妾身樊素。自从绿野堂上。和小姐在夫人行正讲书中间。有白敏中到来。夫人不知主何意。使小姐拜他做哥哥。自此之后。偷视俺小姐。似乎不乐。必有所感。俺小姐是个知礼的人。未尝出那绣房门。为他这般呵。连我也不曾离他半步。我数次劝他后花园中看花去。他坚意的不去。如今正是三月望日。又値清明节近。恰才院公说道。后花园中群花烂熳。万卉争妍。我不管怎生。劝他走一遭去。（见旦儿科）（旦儿云）樊素。你那𥚃去来。我正等你讲书哩。（正旦背云）小姐刬的待要讲书哩。（旦儿云）樊素。我想河出图。洛出书。阴阳判而八卦生。自伏羲神农。传至孔孟。到秦始皇坑儒焚典。其祸烈矣。鲁共王坏孔子故宅。于壁中得诗书六经。以传后世。盖天之未丧斯文也。每览一书。顿觉胸臆开豁。终日无倦。我是一女子。不习女工。而读书若此。不为癖症乎。（正旦云）小姐。但开卷与圣人对面。受益多矣。（唱）
【仙吕点绛唇】
书丧秦嬴。道绝孔圣。坑灰冷。汉代儒生。他每都拨煨烬寻踪影。
【混江龙】
孔安国传中庸语孟。马融集春秋祖述着左丘明。演周易关西夫子。治尚书鲁国伏生。校礼记舛譌杨子云。作毛诗笺注郑康成。无过是阐大道发扬中正。纪善言问答详明。咱祖父乃文林华胄。况外戚是儒业簪缨。哀先相几乎绝嗣。使小姐振厥家声。又何须悬头刺股。积雪囊萤。那𥚃也齐家治国。显姓扬名。但只要动天机。合天理。识天时。顺天道。尽天心。知天命。寸阴是竞。万理咸精。
（旦儿云）我和你再讲一篇书。（正旦云）小姐还要讲书哩。小姐恰才樊素和老夫人去后花园中烧香。见那景物。多有好处。趁此好天良夜。不去赏玩。却不辜负了这春光。不索讲书。喒游玩去来。（旦儿云）圣人云。吾十有五。而志于学。何况我辈乎。（正旦背云）似此文魔。可怎生奈何。则除是恁的。（唱）
【油葫芦】
小姐你罢女工留心在九大经。吾日三省。（旦儿云）日月逝矣。岁不我与。你为甚么不讲书。（正旦唱）则他那匆匆节序又清明。这其间风光老尽芳菲景。今夜个月明闲杀秋千影。（旦儿云）樊素。你到后花园中来么。（正旦云）小姐。且休说那后花园中的景致。你则听者。（旦儿云）教我听甚么那。（正旦唱）你听波杜鹃声到耳清。闻波梨花香拂鼻馨。小姐你把看书心权作游春兴。暂离了三尺短檠灯。
（旦儿云）樊素。不争俺和你闲行。老夫人知道。可怎了也。（正旦唱）
【天下乐】
这其间燕寝夫人梦未醒。（旦儿云）老夫人着你伴我读书。你倒搬逗我废学。（正旦云）若老夫人知道呵。我便道不干小姐事。都是樊素来。（唱）樊素到天明。亲负荆。（带云）樊素搬逗小姐废学。（唱）比着那终南山割席学管宁。（旦儿云）不知你主何意。这早晚只往后花园中去那。（正旦唱）不是我主意儿别。啜赚的你早晚行。（云）岂不闻春宵一刻値千金。（唱）你休辜负了莺花三月景。
（旦儿云）恁的呵。我依着你走一遭去。这事都是你承当。今夜觉有些春寒。等我再添件衣服。你引的我去。（正旦云）喒一同去来。（同下）（白敏中上诗云）
半似明珠半似花。翠翘云鬓总堪夸。
自从识得娇柔面。魂梦悠悠会楚峡。
小生白敏中是也。自从前日。见了小姐一面。恰便似玉天仙的容貌。西施女的妖娆。着小生这两日眠思梦想。茶不茶。饭不饭。老夫人绝然不题这门亲事。今夜晚间。月朗风清。小生比及在这书房中闷坐。我将过这琴来抚一曲咱。琴也。我哀告你咱。想我与足下湖海相随数载。我今抚一曲。都在你个仙人肩。玉女腰。蛇腹断纹。峄阳焦尾。金徽玉轸。七条冰弦之上。天那。怎生借一陈顺风儿。将我这琴声。吹入俺那玉糚成粉捏就的小姐耳朵𥚃面去。将你这琴高阁起。四时祭祀。不敢有失。谨当下拜。（抚琴科云）我抚一曲咱。（正旦上云）小姐。喒悄悄的行将去。（旦儿云）樊素。休要大惊小怪的。俺捏住这玉珮。慢慢的行将去。（正旦唱）
【那咤令】
摇玎𤤮玉声。蹴金莲步轻。蹴金莲步轻。踏苍苔月明。踏苍苔月明。浸凌波袜冷。（云）小姐。你看花红似锦。柳绿如烟。端的是好春光也。（旦儿云）是好景致也。（正旦唱）九十日春意浓。千金价春宵永。端的个乐事难并。
（云）看了这桃红柳绿。是好春光也呵。（唱）
【鹊踏枝】
花共柳笑相迎。风与月更多情。酝酿出嫩绿娇红。淡白深青。对如此良辰美景。可知道动骚人风调才情。
（云）小姐。樊素见这美景良辰。偶成数句。幸勿笑咱。（旦儿云）愿闻。（正旦唱）
【寄生草】
此景翰林才吟难尽。丹青笔画不成。覰海棠风锦机摇动鲛绡冷。芳草烟翠纱笼罩玻璃净。垂杨露绿丝穿透珍珠迸。池中星有如那玉盘乱撒水晶丸。松梢月恰便似苍龙捧出轩辕镜。
（白弹琴科）（旦儿云）樊素。那𥚃这般琴声响亮。（正旦云）必然是白敏中那生抚琴哩。（旦儿云）樊素。他这琴中弹的是何调也。（正旦云）喒悄悄的向那窗儿外听去。（白敏中云）对此佳景。我作歌一首。（歌曰）月明涓涓兮夜色澄。风露凄凄兮隔幽庭。美人不见兮牵我情。鳞鸿杳杳兮信难凭。肠欲断兮愁越。增曲未成兮泪如倾。故乡千里兮身飘零。安得于飞兮离恨平。（旦儿听科云）这生作的词。好伤感人也。（正旦唱）
【幺篇】
他曲未终肠先断。（带云）连我也伤感起来。（唱）俺耳才闻愁越增。一程程挨入相思境。一声声总是相思令。一星星尽诉相思病。不争向琴操中单诉着你飘零。可不道窗儿外更有个人孤另。
（白又弹科）（歌云）孤凤求凰兮空哀鸣。离凰何处兮闻此情。（正旦云）你别弹一曲也罢呵。（唱）
【六幺序】
则管𥚃泣孤凤琴中语。怨离凰指下生。（云）小姐。喒回去来。（旦儿云）樊素。你慌做甚么。（正旦唱）这公他也不是个老实先生。（做惊科云）小姐。兀的不有人来也。（旦儿云）人那𥚃来。（正旦唱）疎剌剌竹弄寒声。扑簌簌花坠残英。忒楞楞宿鸟飞腾。（做听科唱）听沈了半晌空傒幸。静无人悄悄冥冥。（旦儿云）樊素。做甚么大惊小怪的。那得人来。你好疎狂也。（正旦唱）不是我心憍怯。非是我疎狂性。（笑科云）呵呵呵。倒着我笑了一回。（旦儿云）樊素。你笑怎么。（正旦唱）恰才嗤的失笑。喑的吞声。
（白敏中云）这窗外恰便似有人说话。莫不是听琴的么。我开开这书房门看咱。（正旦唱）
【幺篇】
听呀的门扃。似擦的人行。蓦的闻声。魆的潜行。猛的凝睛。淅的零零。煞的风清。却元来群花弄影。他将我来諕一惊。（云）小姐。喒回去罢。则怕有人来也。（旦儿云）再听一曲。怕做甚么那。（正旦唱）这的是小姐分明。樊素实曾。搬调的在后园中。夤夜闲行。只恐怕老夫人知道无干净。别引逗出半点儿风声。夫人他治家严肃狠情性。（云）若老夫人知道呵。他道不干别人事。都是樊素这小贱人。唤过来跪者。（唱）至少呵有三十拄杖。去来波我其实怕的是你那七代先灵。
（云）夜深了也。喒回去来。兀的不有人来了也。（旦儿云）喒回去来。（正旦唱）
【赚煞】
你道信步出兰庭。庭院悄人初静。（旦儿云）这早晚有谁出来。（正旦云）不是别人。（唱）静听是弹琴的那生。（白咳嗽科）（旦儿云）他便知道呵。怎知俺来这𥚃做甚么。（正旦唱）生猜咱无情似有情。（旦儿云）怎知无情似有情。（正旦唱）情知喒甚意来听。（云）夜深了。喒回去来。（旦儿云）这早晚甚么时候了。（正旦唱）听沈罢过初更。更阑也休得消停。（旦儿云）你要来便来。你要去便去。再待些儿怕甚么。（正旦唱）停待甚忙将那脚步儿行。（旦儿云）行到那𥚃去。（正旦唱）行过那梧桐树儿边金井。（旦儿云）因甚么往那𥚃去。（正旦唱）井阑边把身躯儿掩映。（旦儿云）你前面行。我后面跟将去呵。（正旦唱）映着我这影儿呵（旦儿云）樊素。你则道我不看见你哩。（正旦唱）好着我嫌杀月儿明。（下）
（旦儿云）我瞒着樊素。将这香囊儿撇下。撇在那生书房门首。那生若出来呵。他自然看见也。（诗云）
乱落桃花流水去。引将刘阮入天台。
（撇香囊下）（白敏中出门见科云）嗨。原来是小姐在此听琴。可怎生去了。我这𥚃赶将去。嗨。争奈去的远了也。莫非是来偷望小生。我须不知。一定恼将去了。嗨。则是小生无缘。我且回书房中去。这月明之下。是甚物件。（拾起看科云）呀。原来是个香囊儿。这个是小姐故意遗下的。我拿去书房中。仔细看咱。我剔的这灯明亮。上下是两个合欢同心结子。这香囊儿上绣着一把莲满池娇。更有两个交颈鸳鸯儿。这上面有一首诗。我看咱。（诗云）
寂寂深闺𥚃。南容苦夜长。
粉郎休易别。遗赠紫香囊。
原来这香囊儿是小姐故意遗下与小生的。我仔细详解一遍咱。上面这同心结子。他道与我同心合意。中间是一把莲。莲心为藕。他要与小生成其配偶。下面有两个交颈鸳鸯儿。他意中与小生同衾共枕。遂成交颈。这一首诗中。说道寂寂深闺𥚃。他道在深闺。无人知道的去处。南容苦夜长。南容者。古之美妇也。为甚比他做为南容。为他小字小蛮。故比南容也。粉郎休易别。为小生姓白。故说粉郎。休易别。为我累次要辞夫人回家去。他教我休便去了。遗赠紫香囊。故意留与小生为信物。原来小姐向小生却如此留意。从今日起头。那有心弹琴讲书。只索每日晨参暮礼。将此香囊供养者。香囊呵。少不的为你害杀小生也。（诗云）
香囊意重胜黄金。惹的相思透骨侵。
则为多情愁闷冗。何如欢会称其心。
（下）' AND annotation='①綠野堂：晋国公裴府家宴讲书之堂。
②香囊寄诗：小蛮暗绣香囊、内藏含意诗句，撇于白敏中书房门外，作为传情信物。
③南容：古之美妇，此处以小蛮小字作比。粉郎：指姓白的少年（借"傅粉何郎"之典）。
④那咤令、鵲踏枝、寄生草等：首折正旦樊素所唱套曲曲牌。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"争得","explanation":"怎得，怎能。","line":0,"start":0,"end":2,"source_text":"争得才如杜牧之，试来湖上辄题诗。"},{"word":"杜牧之","explanation":"即唐代诗人杜牧，字牧之，以工于写景咏怀著称，多有游览题咏的佳作。","line":0,"start":4,"end":7,"source_text":"争得才如杜牧之，试来湖上辄题诗。"},{"word":"辄","explanation":"就，便。","line":0,"start":12,"end":13,"source_text":"争得才如杜牧之，试来湖上辄题诗。"},{"word":"茶鼓","explanation":"古代寺院中召集众僧饮茶所击的鼓。","line":1,"start":5,"end":7,"source_text":"春烟寺院敲茶鼓，夕照楼台卓酒旗。"},{"word":"卓","explanation":"直立，竖立。","line":1,"start":12,"end":13,"source_text":"春烟寺院敲茶鼓，夕照楼台卓酒旗。"},{"word":"杂芳","explanation":"各种花草的香气。","line":2,"start":2,"end":4,"source_text":"浓吐杂芳薰𪩘崿，湿飞双翠破涟漪。"},{"word":"薰","explanation":"熏染。𪩘崿（yǎn è）：山峰、山崖。","line":2,"start":4,"end":5,"source_text":"浓吐杂芳薰𪩘崿，湿飞双翠破涟漪。"},{"word":"翠","explanation":"指翠鸟。","line":2,"start":11,"end":12,"source_text":"浓吐杂芳薰𪩘崿，湿飞双翠破涟漪。"},{"word":"涟漪","explanation":"水面的微波。","line":2,"start":13,"end":15,"source_text":"浓吐杂芳薰𪩘崿，湿飞双翠破涟漪。"},{"word":"蓑兼笠","explanation":"蓑衣和斗笠，是渔夫的防雨用具。","line":3,"start":4,"end":7,"source_text":"人间幸有蓑兼笠，且上渔舟作钓师。"},{"word":"钓师","explanation":"渔人，渔夫。","line":3,"start":13,"end":15,"source_text":"人间幸有蓑兼笠，且上渔舟作钓师。"}]'::jsonb WHERE id='e7b0eece-5be2-499a-a246-ec1075462d6c' AND content='争得才如杜牧之，试来湖上辄题诗。
春烟寺院敲茶鼓，夕照楼台卓酒旗。
浓吐杂芳薰𪩘崿，湿飞双翠破涟漪。
人间幸有蓑兼笠，且上渔舟作钓师。' AND annotation='①争得：怎得，怎能。杜牧之：即唐代诗人杜牧，字牧之，以工于写景咏怀著称，多有游览题咏的佳作。
②辄：就，便。
③茶鼓：古代寺院中召集众僧饮茶所击的鼓。
④卓：直立，竖立。
⑤杂芳：各种花草的香气。薰：熏染。𪩘崿（yǎn è）：山峰、山崖。
⑥翠：指翠鸟。涟漪：水面的微波。
⑦蓑兼笠：蓑衣和斗笠，是渔夫的防雨用具。
⑧钓师：渔人，渔夫。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"玉簪","explanation":"小蛮临别赠物，作为信物，暗示白敏中勿忘旧约、早取功名。","line":40,"start":31,"end":33,"source_text":"（白敏中云）小姐别有甚么嘱付小生的言语。（正旦云）小姐赠与足下玉簪一枝。金凤钗一只。你知道其意么。（白敏中云）不知。小姐送我玉簪金钗。却主何意。（正旦唱）"},{"word":"玉簪","explanation":"小蛮临别赠物，作为信物，暗示白敏中勿忘旧约、早取功名。","line":40,"start":62,"end":64,"source_text":"（白敏中云）小姐别有甚么嘱付小生的言语。（正旦云）小姐赠与足下玉簪一枝。金凤钗一只。你知道其意么。（白敏中云）不知。小姐送我玉簪金钗。却主何意。（正旦唱）"},{"word":"玉簪","explanation":"小蛮临别赠物，作为信物，暗示白敏中勿忘旧约、早取功名。","line":42,"start":7,"end":9,"source_text":"俺小姐情坚如碧玉簪。心赤如黄金凤。意不别你个白衣相。（白敏中云）小姐还有甚么分付小生来。（正旦云）呀。争些儿把来忘了。（唱）两件事教先生行拜上。（白敏中云）那两件事那。（正旦云）小姐道。你若是凤墀得志。雁塔题名。可早来呵。（唱）做俺这有情的相国状元郎。（白敏中云）那一件却是甚么。（正旦云）则不要教人骂你。（唱）骂你做薄幸的长安少年党。（下）"}]'::jsonb WHERE id='ed4a9957-1758-48e6-b1da-dfa3d2ac333f' AND content='（白敏中上诗云）
万籁无声自寂寥。一轮明月上花梢。
庭阶竚立痴心望。盼杀姮娥下九霄。
小生白敏中。感蒙小姐不弃。许我今宵赴约。这早晚还不见来。小娘子。你若不来呵。我这病覰天远入地近。眼见的无那活的人也。（看天科云）日头可也还早哩。我且看几行书咱。天也。我有甚么心肠看这书。这早晚不知是甚么时候。我试看咱。呀。才午时也。天也。偏生今日这样长。我试吟诗咱。读书继晷怕黄昏。不觉西沈强掩门。欲赴海棠花下约。太阳何故又生根。呀。可早未时也。我且坐一坐。（坐科云）我怎生坐的住。我再看咱。天也。可怎生还是未时我央及你咱。我与你唱喏。怎生不动。我与你下跪又不动。我与你下拜也不动。呸。鳔胶粘住你哩。泼毛团好无礼也。小生不才杀波。也是个白衣卿相。今日用着你。故意的不晚。你则道我不认的你哩。当日尧王时。有十个日头。被后羿在昆仑山顶上。射落九个。止留你一个。你晓来夜去。催迫了多少好人。你若是懽喜呵。腆着你那红馥馥的脸儿。你苦恼了呵。云生在东南。雾长在西北。你听者。无端三足乌。团团光闪烁。安得后羿弓。射此一轮落。呀。便好道人有善愿。天必从之。头𥚃未曾闹他时。还是未时。方才闹了呵。可早日头落了也。呀。鼓楼上可早发擂也。可早撞钟也。小生在此。等候小姐。这早晚敢待来也。（正旦上云）妾身樊素。我收拾下香卓儿了。请俺小姐烧香去来。我想白敏中可谓端谨之士。从见小姐。荏苒成病。几乎丧命。将平日所学。一旦废矣。正好道只因天下美人面。改尽世间君子心。此事若非妾在其中说诱骗吓。焉能成得。如今瞒着夫人。推烧夜香。着俺小姐和那生赴约去。正是一股金钗半边镜。世间多少断肠人。（唱）
【越调鬭鹌鹑】
想着那星斗文章。几回家逢咱稽颡。只为那花月精神。一见了教人断肠。用了我说六国喉舌。下三齐智量。不甫能添了晚妆。推烧夜香。如此般月白风清。花浓气爽。
【紫花儿序】
月溶溶梨花庭院。风淡淡杨柳楼台。雾蒙蒙芳草池塘。如此般好天良夜。淑女才郎。相将。意厮投门厮对户厮当。成就了只凤孤凰。这一个夜月南楼。那一个窥视东墙。
【小桃红】
那生敢倚书窗想像赴高唐。（白敏中向前搂旦科云）小姐。你来了也。（正旦慌科云）是谁。（白敏中云）是我。（正旦唱）吓得我可扑扑小鹿儿心头撞。偌早晚是谁人敢无状。（白敏中云）我则道是小姐来了。（正旦唱）可怎生恁风狂。（白敏中云）我不想是小娘子。你恕罪咱。（正旦云）可早是我哩。是夫人呵。可怎生了也。（唱）若是俺夫人撞见如何讲。（白敏中云）是小生病的这般昏了也。（正旦唱）便道是害的你神魂荡漾。你也合将眼皮开放。你常好是热蟒也沈东阳。
（云）先生。你且在那厢等着。俺小姐便来也。（旦儿上云）天色晚了也。我烧香去。（正旦云）小姐。你烧香咱。（旦儿云）樊素。将香盒儿来者。（正旦云）小姐。香盒儿在此。（旦儿云）我拈香咱。此一炷香。愿亡过父亲。早生天界。第二炷香。愿在堂老母安康。（正旦背云）我听小姐这一炷香可愿谁。（旦儿云）我没的愿。（正旦云）我与小姐说明。这一愿。则愿的俺小姐嫁一个风风流流。可可喜喜。标标致致好姐夫也。拖带樊素咱。（旦儿云）你看这贱人。（正旦向白云）先生。那花阴之下。烧香的不是俺小姐。（白敏中云）小生敢去也不敢去。（正旦云）先生。你去不妨。（白敏中云）小生读圣贤之书。夤夜与女子相期。莫是非礼么。（正旦唱）
【鬼三台】
呸。这的是赴约的风流况。须不是乐道的颜回巷。（白敏中云）子钓而不纲。弋不射宿。（正旦唱）哎。那𥚃也歪谈乱讲。（白敏中云）小生敢去么。（正旦云）先生。我问你咱。（白敏中云）问小生些甚么。（正旦唱）你因甚么病在膏肓。（白敏中云）小生则为小姐来。（正旦云）你既为小姐呵。你过去波。（白敏中云）是好月色也。（正旦唱）百忙𥚃卖弄甚么风清月朗。（白敏中云）我向小姐跟前去。怎么百般的那不动这脚步也。（正旦唱）当初那不能彀时害的来狂上狂不甫能得相见諕的来慌上慌。（白敏中云）见了小姐。不由的我心头忒忒的怕将起来。（正旦唱）见他时胆战心惊。把似你无人处休眠思梦想。
（白敏中云）过去不妨么。（正旦云）你过去不妨事。（唱）
【金蕉叶】
这的是桃源洞花开艳阳。须不比祆庙火烟飞浩荡。（正旦推白云）去。（旦儿叫云）是甚么人。（白慌科云）是小生。（正旦唱）阳台上云雨渺茫。可做了蓝桥水洪波泛涨。
（旦儿怒科云）却原来是白敏中。你既读孔圣之书。必达周公之礼。你这般行径。是何相待也。（白敏中云）兀的不羞杀小生也。（正旦云）呀。小姐变了卦也。白敏中。你那背地𥚃嘴那𥚃去了。（唱）
【调笑令】
劈面的便抢。和俺那病襄王。呀。怎生来翻悔了巫山窈窕娘。满口儿之乎者也无拦当。用不着恭俭温良。諕的那有情人恨无个地缝儿藏。（带云）毛毛羞么。（唱）羞杀我也傅粉何郎。
（白敏中云）百忙中你也花白我。（正旦唱）
【秃厮儿】
请学士休心劳意攘。俺小姐则是作耍难当。（旦儿打正旦科云）谁着你这早晚引将他来。（正旦云）小姐休闪了手。（笑科唱）这的是我传书寄简请受的赏。谁承望。向咱行。倒有风霜。
（旦儿怒科云）这一场都是樊素辱门败户的小贱人。（正旦唱）
【圣药王】
他道是这一场。这一桩。都是这辱门败户小婆娘。（旦儿云）我告夫人去也。（正旦冷笑科唱）杀人呵要见伤。拿贼呵要见赃。（白怕跪科云）望小姐怜小生咱。（正旦唱）请起来波多愁多病俏才郎。（出香囊科）（带云）打睃。（唱）这是谁与他的紫香囊。
（旦儿云）好姐姐。我鬭你耍哩。（正旦云）我却疼哩。（白起身科云）则被你諕杀我也。（旦儿云）有人来也。（夫人撞上咳嗽众做慌科）（正旦唱）
【麻郎儿】
这声音九分儿是你令堂。（夫人云）这一定是樊素小贱人。（正旦唱）呀。头一句先抓揽着梅香。（旦儿慌科云）是谁。（正旦云）小姐。悄悄的。是老夫人来了。（旦儿云）樊素。直被你引的老夫人来。可怎了也。（正旦唱）您吵闹起花烛洞房。自支吾待月西厢。
（旦儿云）樊素。老夫人问我。可着我推甚么。（正旦扯旦儿科）（唱）
【幺篇】
哎。不妨。（白敏中云）小娘子可怎了也。（正旦指白科唱）莫慌。（指自科唱）我当。（夫人云）先唤过樊素那小贱人来。（白敏中向旦云）小姐。望你遮盖俺咱。（正旦云）小姐。你受责呵。理之当然。我可图些甚么来。（旦儿云）罢么。好姐姐。你先过去。你自回的好着么。（正旦云）由他。你两个只在这𥚃。我过去见夫人。若说得过呵。你休欢喜。说不过呵。你休烦恼。（见夫人科）（夫人云）小贱人跪者。（正旦跪科）（夫人云）小贱人你知罪么。（正旦云）我不知罪。（夫人打科云）这小贱人。你还说不知。你做的好勾当哩。（正旦唱）亲生女非比他行。家丑事不可外扬。（夫人云）谁着你引着小姐。往后花园中。看白敏中去来。你若实说呵。我便饶了你。你若不实说呵。我打死你个小贱人。（正旦云）谁见来。（夫人打科云）我亲自撞见。你还强嘴。（正旦云）老夫人休打闪了手。此非妾之罪。皆夫人之过也。（唱）你索取一个治家不严的招状。
（夫人云）这小贱人。连我也指攀着。（正旦云）请夫人息雷霆之怒。容贱妾陈是非之由。当日先相国临终遗言。道夫人将小姐纳白敏中为婿。为报参军救死之恩。如违我之遗言。我死不瞑目。言犹在耳。白敏中到来。不审夫人何意。却令小姐以兄妹之礼相见。既然如此。只合将白敏中送于别馆安下。厚赆他还乡。以绝其望。却留在后花园中万卷堂上居住。使佳人才子。临风对月。心非木石。岂无所思。妾身之罪。固不可逃。夫人之愆。亦不可免也。（夫人云）我却有甚罪。（正旦云）夫人有四罪。（夫人云）我有那四罪。（正旦云）不从相国遗言。罪之一也。不能治家。罪之二也。不能报白氏之恩。罪之三也。不能蔽骨肉之丑。罪之四也。（唱）
【络丝娘】
自寻思识礼义尊严使长。（云）我想孟母为子三迁。陵母为子伏剑。陶母为子剪发。曾母为子投梭。古来贤者。后代扬名。（唱）几曾做这般出丑腤臜勾当。（夫人云）你这般说呵。罢了那。（正旦唱）罢不罢休不休乞个明降。（夫人云）罢罢罢。这妮子倒连我也指下来。想起来则是我养女儿不气长。都是我的不是了也。（正旦唱）既恁的呵只合着他两个同归鸳帐。
（夫人打科云）小贱人倒只由你那。我不饶你。与我唤过小蛮来。（正旦起出见旦云）小姐。且喜老夫人将那棍子。则是滴溜溜的打在我这身上。被我比长比短。一遍说过了。老夫人如今叫你过去哩。（旦儿云）羞人答答的。怎么去见母亲。（正旦云）娘跟前。有甚么羞。你见去规闭了眼者。（旦见夫人跪科）（夫人云）好小贱人。你羞么。我怎么抬举你来。岂不闻男婚女配。古之常礼。你今日做下这等勾当。我是个不戴头巾的男子。兀的不气杀我也。（做喝科云）小贱人。且回房中去。明日和你理会。唤过那小禽兽来。（旦下）（正旦见白科云）先生。俺小姐招了也。老夫人着你过去哩。（白敏中云）小生惶恐。怎么见老夫人。（正旦云）不妨事。休佯小心。老着脸子过去。（白见夫人科）（夫人云）小禽兽。你羞么。怎么做那读书人。我着你兄妹为之。却做下这等勾当。有那般贤明父母。生下你这不肖儿男。我待声扬呵。知道的是你个小禽兽无理。不知道的说俺家忘了人大恩。我若不看你那亡过的父亲面呵。唤宅院𥚃人来打坏了你。等到天明钟声罢。便离了我家去。呸。小后生家不存心于功名。却向那女色上留心。我看你再有甚么脸见我来。（下）（正旦背听科）（白敏中云）羞杀我也。这𥚃不可久留。等到五更钟声罢呵。便索离他家门去也。（正旦云）先生。你休烦恼。（唱）
【雪𥚃梅】
你好壮脸也画眉郎。（白敏中云）都着你的道儿。（正旦唱）并不曾干多口小红娘。（白敏中云）我这𥚃不敢再住。须索上朝应举去也。你叫小姐见我一面儿去也好。（正旦唱）俺姐姐道足下不须悒怏。好事也从来魔障。（带云）俺小姐道来。（唱）只教你把心儿放长。
（白敏中云）小姐既有此心。休傒落我也。（正旦唱）
【青山口】
哎。不妨不妨你走将来效鸾凰。女孩儿须是慌。（白敏中云）这都是小生命薄。偏生逢着夫人走将来的快也。（正旦唱）左想右想全不想。可可的老夫人偏撞上。你便有口呵怎对当。好羞惭做这场。教你收拾书箱。打迭行装。便赴科场。献策君皇。两袖天香。一部笙簧。宴罢琼林出建章。车盖轩昂。祗候成行。乡也么乡却还乡。堂也么堂拜高堂。子母商量。旧约难忘。锦屏前花烛辉煌。那时节也替我撮合山妆一个谎。
（白敏中云）小姐别有甚么嘱付小生的言语。（正旦云）小姐赠与足下玉簪一枝。金凤钗一只。你知道其意么。（白敏中云）不知。小姐送我玉簪金钗。却主何意。（正旦唱）
【收尾】
俺小姐情坚如碧玉簪。心赤如黄金凤。意不别你个白衣相。（白敏中云）小姐还有甚么分付小生来。（正旦云）呀。争些儿把来忘了。（唱）两件事教先生行拜上。（白敏中云）那两件事那。（正旦云）小姐道。你若是凤墀得志。雁塔题名。可早来呵。（唱）做俺这有情的相国状元郎。（白敏中云）那一件却是甚么。（正旦云）则不要教人骂你。（唱）骂你做薄幸的长安少年党。（下）
（白敏中云）天色明了也。小生收拾行装。求取功名。走一遭去。（诗云）
才见开花骤雨催。团圆明月忽云迷。
渔翁偶入荷花荡。打散鸳鸯各自飞。
（下）' AND annotation='①越調：第三折换用越调（鬬鵪鶉、紫花兒序等），北曲每折一宫的惯例。
②描眉郎/畫眉：化用张敞画眉之美谈，指情郎。
③落霞、花燭洞房：写月下赴约、老夫人撞破的紧张场面。
④玉簪、金鳳釵：小蛮临别赠物，作为信物，暗示白敏中勿忘旧约、早取功名。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"水明楼","explanation":"楼名，在今江苏常州，位于东坡古渡附近，为当地名胜。","line":0,"start":0,"end":3,"source_text":"水明楼下涨纹平，柳外遥山抹黛轻。"},{"word":"涨纹平","explanation":"春水上涨，水面波纹平缓。","line":0,"start":4,"end":7,"source_text":"水明楼下涨纹平，柳外遥山抹黛轻。"},{"word":"抹黛轻","explanation":"形容远处的青山如同被轻轻抹上了一层青黑色的颜料，黛是古代女子画眉用的青黑色颜料，此处喻山色。","line":0,"start":12,"end":15,"source_text":"水明楼下涨纹平，柳外遥山抹黛轻。"},{"word":"共清明","explanation":"指与故友邵仲游一同度过清明时节的过往经历。","line":1,"start":12,"end":15,"source_text":"二月江南好风景，故人此日共清明。"},{"word":"征鸿","explanation":"远飞的大雁，古人常借大雁传书的典故代指传信的使者。","line":2,"start":0,"end":2,"source_text":"征鸿归尽书难寄，燕子来时雨易成。"},{"word":"雨易成","explanation":"江南二月春雨频繁，很容易落下。","line":2,"start":12,"end":15,"source_text":"征鸿归尽书难寄，燕子来时雨易成。"},{"word":"舣舟亭","explanation":"古迹名，在常州东郊，相传为宋代苏轼停舟登岸之处，舣舟即停船靠岸。","line":3,"start":2,"end":5,"source_text":"寻遍舣舟亭畔路，送君行处草初生。"}]'::jsonb WHERE id='f17647f9-a400-41ce-a8d7-0005c7e44eed' AND content='水明楼下涨纹平，柳外遥山抹黛轻。
二月江南好风景，故人此日共清明。
征鸿归尽书难寄，燕子来时雨易成。
寻遍舣舟亭畔路，送君行处草初生。' AND annotation='①水明楼：楼名，在今江苏常州，位于东坡古渡附近，为当地名胜。涨纹平：春水上涨，水面波纹平缓。
②抹黛轻：形容远处的青山如同被轻轻抹上了一层青黑色的颜料，黛是古代女子画眉用的青黑色颜料，此处喻山色。
③共清明：指与故友邵仲游一同度过清明时节的过往经历。
④征鸿：远飞的大雁，古人常借大雁传书的典故代指传信的使者。
⑤雨易成：江南二月春雨频繁，很容易落下。
⑥舣舟亭：古迹名，在常州东郊，相传为宋代苏轼停舟登岸之处，舣舟即停船靠岸。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"紫塞","explanation":"泛指边塞。","line":1,"start":0,"end":2,"source_text":"紫塞冒风沙，谩区区两鬓生华。归来好向林泉下。买牛卖剑，求田问舍，学圃耘瓜。"},{"word":"谩","explanation":"徒然、空泛。","line":1,"start":6,"end":7,"source_text":"紫塞冒风沙，谩区区两鬓生华。归来好向林泉下。买牛卖剑，求田问舍，学圃耘瓜。"},{"word":"买牛卖剑","explanation":"化用汉龚遂劝农、卖剑买犊之典，表弃武归农。","line":1,"start":22,"end":26,"source_text":"紫塞冒风沙，谩区区两鬓生华。归来好向林泉下。买牛卖剑，求田问舍，学圃耘瓜。"},{"word":"求田问舍","explanation":"买田置屋，指过安顿的田园生活。","line":1,"start":27,"end":31,"source_text":"紫塞冒风沙，谩区区两鬓生华。归来好向林泉下。买牛卖剑，求田问舍，学圃耘瓜。"},{"word":"群蚁阵","explanation":"蚁阵、蜂衙皆喻尘世争竞，厌恶其扰攘。","line":5,"start":14,"end":17,"source_text":"清耳目，欲慕许由家。苔砌倦观群蚁阵，花房嫌听乱蜂衙，犹是厌喧哗。"},{"word":"乱蜂衙","explanation":"蚁阵、蜂衙皆喻尘世争竞，厌恶其扰攘。","line":5,"start":22,"end":25,"source_text":"清耳目，欲慕许由家。苔砌倦观群蚁阵，花房嫌听乱蜂衙，犹是厌喧哗。"},{"word":"若蝇蜗","explanation":"如蝇逐臭、如蜗角之争，比喻为名利所困之渺小。","line":7,"start":20,"end":23,"source_text":"醉醒须在咱，清浊任从他。竞名利，争头角，若蝇蜗。"},{"word":"皇宣省札","explanation":"皇帝的宣布、官府的文札。","line":9,"start":42,"end":46,"source_text":"不羡穿红骑马，准便玩水观霞。自去携鱼换酒，客来汲水烹茶。家存四壁，诗书抵万金价。岂望皇宣省札，壮士持鞭，佳人捧斝。草堂深况亦幽嘉，自然身退天之道，免得刑罚。拖藜杖芒鞋刺塔，穿布袍麻绦搭撒，捻衰髯短发髿〔前一字字形待核〕。从人笑从人笑，道咱甚娘势霎。篱生竹笋，径落松花。"},{"word":"斝","explanation":"古代酒器。","line":9,"start":55,"end":56,"source_text":"不羡穿红骑马，准便玩水观霞。自去携鱼换酒，客来汲水烹茶。家存四壁，诗书抵万金价。岂望皇宣省札，壮士持鞭，佳人捧斝。草堂深况亦幽嘉，自然身退天之道，免得刑罚。拖藜杖芒鞋刺塔，穿布袍麻绦搭撒，捻衰髯短发髿〔前一字字形待核〕。从人笑从人笑，道咱甚娘势霎。篱生竹笋，径落松花。"},{"word":"青史凌烟","explanation":"青史指史册，凌烟指唐太宗凌烟阁画功臣像，喻功名显赫。","line":15,"start":52,"end":56,"source_text":"尘事远狂交疏人情寡，终朝把草堂门亚。引睡翻书卧吟棍，觉来时性静神澄兴雅。唱道想半纸功名，到头身与祸孰多？青史凌烟姓名挂，也则是渔樵一场话。"},{"word":"渔樵一场话","explanation":"最终不过是渔樵闲谈的一桩逸事。","line":15,"start":63,"end":68,"source_text":"尘事远狂交疏人情寡，终朝把草堂门亚。引睡翻书卧吟棍，觉来时性静神澄兴雅。唱道想半纸功名，到头身与祸孰多？青史凌烟姓名挂，也则是渔樵一场话。"}]'::jsonb WHERE id='f61d5ac9-356e-44fa-b845-891c019215a6' AND content='〔青杏子〕
紫塞冒风沙，谩区区两鬓生华。归来好向林泉下。买牛卖剑，求田问舍，学圃耘瓜。
〔归塞北〕
争似我，恬淡作生涯。切意采芝编药篓，留心垂钓棹鱼艖，汾水岸晋山坡。
〔幺篇〕
清耳目，欲慕许由家。苔砌倦观群蚁阵，花房嫌听乱蜂衙，犹是厌喧哗。
〔憨郭郎〕
醉醒须在咱，清浊任从他。竞名利，争头角，若蝇蜗。
〔还京乐〕
不羡穿红骑马，准便玩水观霞。自去携鱼换酒，客来汲水烹茶。家存四壁，诗书抵万金价。岂望皇宣省札，壮士持鞭，佳人捧斝。草堂深况亦幽嘉，自然身退天之道，免得刑罚。拖藜杖芒鞋刺塔，穿布袍麻绦搭撒，捻衰髯短发髿〔前一字字形待核〕。从人笑从人笑，道咱甚娘势霎。篱生竹笋，径落松花。
〔净瓶儿〕
字草蛇形耍，笔钝兔毫乏。瑶琴横几，宝剑归匣。清佳，乐潇洒，亲采云根镌砚瓦。书盈架，粉笺墨点色色翻鸦。
〔好观音〕
让客新棋一局罢，闲披览古名人画。一炷山檀瑞烟发，好风来，满座清风飒。
〔尾〕
尘事远狂交疏人情寡，终朝把草堂门亚。引睡翻书卧吟棍，觉来时性静神澄兴雅。唱道想半纸功名，到头身与祸孰多？青史凌烟姓名挂，也则是渔樵一场话。' AND annotation='①紫塞：泛指边塞。谩：徒然、空泛。
②买牛卖剑：化用汉龚遂劝农、卖剑买犊之典，表弃武归农。求田问舍：买田置屋，指过安顿的田园生活。
③汾水晋山：汾水在山西，晋山即山西的山，作者家乡所在，泛指故园山水。
④遽羡许由：上古高士许由隐居箕山，此以许由自比。
⑤群蚁阵、乱蜂衙：蚁阵、蜂衙皆喻尘世争竞，厌恶其扰攘。
⑥若蝇蜗：如蝇逐臭、如蜗角之争，比喻为名利所困之渺小。
⑦皇宣省札：皇帝的宣布、官府的文札。
⑧斝：古代酒器。
⑨青史凌烟：青史指史册，凌烟指唐太宗凌烟阁画功臣像，喻功名显赫。
⑩渔樵一场话：最终不过是渔樵闲谈的一桩逸事。' AND annotation_notes IS NULL;
 UPDATE public.poems SET annotation_notes='[{"word":"天命之谓性","explanation":"天所赋予人的禀赋叫做本性。","line":0,"start":0,"end":5,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"率性","explanation":"遵循本性。","line":0,"start":6,"end":8,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"修道","explanation":"修明道德。","line":0,"start":12,"end":14,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"教","explanation":"教化。","line":0,"start":16,"end":17,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"须臾","explanation":"片刻。","line":0,"start":24,"end":26,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"戒慎","explanation":"警惕谨慎。","line":0,"start":39,"end":41,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"恐惧","explanation":"敬畏。莫见乎隐，莫显乎微：没有比在隐晦之处更易显现，没有比在细微之事上更易彰显的。","line":0,"start":47,"end":49,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"中","explanation":"情绪未发时不偏不倚的状态。","line":0,"start":83,"end":84,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，天地位焉，万物育焉。"},{"word":"中","explanation":"情绪未发时不偏不倚的状态。","line":0,"start":88,"end":89,"source_text":"天命之谓性，率性之谓道，修道之谓教。道也者，不可须臾离也，可离非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。莫见乎隐，莫显乎微。故君子慎其独也。喜怒哀乐之未发，谓之中；发而皆中节，谓之和；中也者，天下之大本也；和也者，天下之达道也。致中和，